window.QB_TKP_B7 = [
{id:"TKP-901", q:"Seorang pelaku UMKM kebingungan karena pengajuan Nomor Induk Berusaha (NIB) melalui OSS selalu gagal pada tahap verifikasi email. Ia datang ke loket PTSP dengan wajah panik karena butuh NIB untuk pengajuan modal usaha minggu depan. Sikap Anda:", opts:[{t:"Mendampingi langkah demi langkah hingga NIB terbit, lalu mencatat kendalanya untuk bahan evaluasi layanan.", s:5},{t:"Memberikan panduan tertulis dan nomor layanan bantuan agar ia bisa mencoba sendiri di rumah.", s:4},{t:"Menyarankan ia membaca panduan di situs OSS dan mencoba lagi nanti.", s:3},{t:"Memintanya datang lagi besok karena antrean sedang panjang.", s:2},{t:"Menyuruhnya mengurus sendiri karena pendampingan bukan tugas loket.", s:1}], ex:"Skor 5: proaktif, tuntas, dan berorientasi solusi — pendampingan penuh plus perbaikan sistemik lewat pencatatan kendala."},
{id:"TKP-902", q:"Seorang warga lanjut usia ingin mengurus izin usaha warungnya tetapi tidak memiliki ponsel pintar, padahal pendaftaran kini wajib melalui aplikasi. Ia tampak malu dan hendak pulang. Sikap Anda:", opts:[{t:"Membantu menginputkan data melalui perangkat kantor sesuai prosedur sambil mendampinginya hingga selesai.", s:5},{t:"Memintanya pulang dan kembali didampingi anak atau keluarganya.", s:4},{t:"Mengarahkannya ke layanan manual tanpa mendampingi prosesnya.", s:3},{t:"Menolak melayani karena semua pendaftaran harus dilakukan secara mandiri lewat aplikasi.", s:2},{t:"Membiarkannya pulang tanpa berusaha membantu.", s:1}], ex:"Skor 5: inklusif dan tuntas — memanfaatkan fasilitas kantor untuk menjembatani kesenjangan digital warga lansia."},
{id:"TKP-903", q:"Berkas permohonan Persetujuan Bangunan Gedung (PBG) seorang warga kurang satu dokumen, yaitu gambar teknis yang disahkan. Warga tersebut sudah antre dua jam dan memohon agar berkasnya tetap diproses. Sikap Anda:", opts:[{t:"Menerima berkas, memberi tanda terima, serta menjelaskan rinci dokumen yang kurang berikut batas waktu pelengkapannya.", s:5},{t:"Menolak berkas dengan penjelasan yang tenang tentang syarat yang harus dipenuhi.", s:4},{t:"Menyuruhnya melengkapi dulu tanpa penjelasan rinci.", s:3},{t:"Menerima berkasnya lalu mendiamkannya di tumpukan.", s:2},{t:"Menerima berkas dengan syarat ada 'uang percepatan'.", s:1}], ex:"Skor 5: tegas pada aturan namun tetap melayani — kepastian prosedur plus kejelasan bagi pemohon."},
{id:"TKP-904", q:"Permohonan izin usaha seorang warga ditolak karena lokasi usahanya berada di zona yang tidak diperuntukkan. Ia marah-marah di ruang pelayanan dan menuduh petugas tidak adil. Sikap Anda:", opts:[{t:"Mendengarkan keluhannya, menjelaskan dasar aturan zonasi dengan tenang, lalu menawarkan alternatif lokasi yang sesuai.", s:5},{t:"Menjelaskan dasar penolakan sesuai peraturan dengan nada tenang.", s:4},{t:"Memanggil petugas keamanan untuk menenangkannya.", s:3},{t:"Berdebat dengannya untuk mempertahankan keputusan.", s:2},{t:"Mengubah keputusan menjadi lolos karena takut dimarahi.", s:1}], ex:"Skor 5: empati + ketegasan + solusi — aturan ditegakkan tanpa mengorbankan martabat pemohon."},
{id:"TKP-905", q:"Antrean di mal pelayanan publik membludak pada jam sibuk. Banyak pemohon mengeluh dan sebagian mulai emosi. Anda adalah petugas yang berjaga. Sikap Anda:", opts:[{t:"Membuka loket tambahan, mengatur ulang nomor antrean, dan memberi prioritas pada lansia serta penyandang disabilitas.", s:5},{t:"Meminta maaf kepada pemohon dan mempercepat proses pelayanan.", s:4},{t:"Tetap melayani seperti biasa sesuai urutan antrean.", s:3},{t:"Menyalahkan pemohon yang datang kesiangan.", s:2},{t:"Menutup loket untuk istirahat lebih lama agar antrean bubar sendiri.", s:1}], ex:"Skor 5: responsif dan adaptif — mengambil inisiatif manajerial untuk mengurai masalah, bukan sekadar bertahan."},
{id:"TKP-906", q:"Seorang penyandang disabilitas pengguna kursi roda datang mengurus perpanjangan izin usaha. Antrean sedang panjang dan akses menuju loket cukup sempit. Sikap Anda:", opts:[{t:"Melayaninya melalui jalur prioritas dan memastikan aksesnya nyaman selama proses berlangsung.", s:5},{t:"Mendahulukannya dari antrean yang ada.", s:4},{t:"Melayaninya seperti pemohon lain sesuai urutan.", s:3},{t:"Memintanya tetap menunggu giliran antrean.", s:2},{t:"Menolak melayani dengan alasan fasilitas belum siap.", s:1}], ex:"Skor 5: pelayanan inklusif yang aktif — bukan sekadar mendahulukan, tapi memastikan kenyamanan akses."},
{id:"TKP-907", q:"Seorang wajib pajak protes karena tagihan PBB-nya membengkak akibat denda keterlambatan. Ia mengaku tidak tahu ada jatuh tempo dan menuduh petugas tidak pernah memberi tahu. Sikap Anda:", opts:[{t:"Menjelaskan perhitungan denda secara transparan, menunjukkan dasar aturannya, serta menginformasikan cara dan jadwal pembayaran.", s:5},{t:"Menjelaskan bahwa denda sudah sesuai peraturan yang berlaku.", s:4},{t:"Menyuruhnya membayar saja tanpa banyak penjelasan.", s:3},{t:"Mengancam akan menyita asetnya bila tidak segera membayar.", s:2},{t:"Menghapus dendanya diam-diam agar ia tidak protes lagi.", s:1}], ex:"Skor 5: transparan dan edukatif — mengubah protes menjadi pemahaman lewat keterbukaan informasi."},
{id:"TKP-908", q:"Sejumlah pedagang pasar memprotes kenaikan tarif retribusi yang mereka anggap memberatkan. Mereka berkumpul di kantor dinas meminta penjelasan. Sikap Anda:", opts:[{t:"Menyosialisasikan dasar kenaikan, manfaatnya bagi fasilitas pasar, serta menyampaikan saluran keberatan resmi yang tersedia.", s:5},{t:"Menjelaskan dasar peraturan kenaikan tarif dengan tenang.", s:4},{t:"Menyuruh mereka membaca sendiri peraturan daerahnya.", s:3},{t:"Mengabaikan protes dan kembali bekerja.", s:2},{t:"Mengancam mencabut hak sewa lapak bagi yang protes.", s:1}], ex:"Skor 5: komunikatif dan akuntabel — membuka ruang dialog resmi, bukan membungkam aspirasi."},
{id:"TKP-909", q:"Dua warga bertengkar di ruang pelayanan karena memperebutkan batas tanah yang masing-masing klaim sebagai miliknya. Suasana memanas dan pemohon lain terganggu. Sikap Anda:", opts:[{t:"Menenangkan keduanya, mendengarkan masing-masing pihak, lalu mengarahkan ke mediasi resmi dan mencatat pokok permasalahannya.", s:5},{t:"Mengarahkan keduanya ke kantor pertanahan untuk penyelesaian.", s:4},{t:"Menyuruh mereka menyelesaikan sendiri di luar kantor.", s:3},{t:"Membela warga yang datang lebih dulu.", s:2},{t:"Mengusir keduanya dari ruang pelayanan.", s:1}], ex:"Skor 5: netral, menenangkan, dan prosedural — meredam konflik sekaligus membuka jalur penyelesaian resmi."},
{id:"TKP-910", q:"Seorang calon investor menanyakan insentif dan prosedur perizinan berinvestasi di daerah Anda. Ia tampak serius namun belum memahami alur birokrasi di Indonesia. Sikap Anda:", opts:[{t:"Memberikan data dan penjelasan lengkap, mendampingi prosesnya, serta menghubungkannya dengan OPD terkait.", s:5},{t:"Memberikan brosur dan penjelasan umum tentang prosedurnya.", s:4},{t:"Mengarahkannya membaca informasi di situs web resmi.", s:3},{t:"Menyuruhnya bertanya ke pemerintah provinsi saja.", s:2},{t:"Mengabaikannya karena investasinya belum pasti terealisasi.", s:1}], ex:"Skor 5: proaktif menarik investasi — pendampingan penuh lintas OPD menunjukkan profesionalisme pelayanan."},
{id:"TKP-911", q:"Kelompok UMKM produsen makanan ringan ingin mengurus sertifikasi halal agar produknya bisa masuk ritel modern, tetapi tidak tahu harus mulai dari mana. Sikap Anda:", opts:[{t:"Memfasilitasi pendaftaran, mendampingi prosesnya, dan menghubungkan mereka dengan pendamping halal hingga sertifikat terbit.", s:5},{t:"Memberikan informasi prosedur dan alamat lembaga penerbit sertifikasi.", s:4},{t:"Mengarahkan mereka mengurus sendiri ke lembaga terkait.", s:3},{t:"Mengaku tidak tahu menahu soal sertifikasi halal.", s:2},{t:"Menolak membantu karena di luar tugas pokok.", s:1}], ex:"Skor 5: fasilitatif dan tuntas — membantu UMKM naik kelas lewat pendampingan sampai hasil."},
{id:"TKP-912", q:"Permohonan izin operasional sebuah klinik harus diverifikasi kelengkapan tenaga kesehatannya. Pemilik klinik menekan agar izin segera terbit karena sudah terlanjur merekrut karyawan. Sikap Anda:", opts:[{t:"Melakukan verifikasi teliti sesuai standar, memberi masukan perbaikan bila ada kekurangan, tanpa terpengaruh tekanan.", s:5},{t:"Memverifikasi sesuai SOP apa adanya.", s:4},{t:"Meloloskan cepat tanpa pemeriksaan mendalam.", s:3},{t:"Mempersulit prosesnya agar pemilik jera menekan petugas.", s:2},{t:"Meminta imbalan sebagai syarat percepatan.", s:1}], ex:"Skor 5: profesional dan berintegritas — standar keselamatan publik tidak bisa ditawar oleh tekanan."},
{id:"TKP-913", q:"Sebuah koperasi simpan pinjam di wilayah Anda bermasalah: banyak anggota gagal menerima kembali simpanannya dan pengurus sulit dihubungi. Para anggota datang meminta bantuan. Sikap Anda:", opts:[{t:"Membina pengurus, berkoordinasi dengan dinas koperasi, dan mengupayakan perlindungan hak anggota.", s:5},{t:"Melaporkan kasusnya ke dinas koperasi untuk ditindaklanjuti.", s:4},{t:"Menyuruh para anggota bersabar menunggu itikad baik pengurus.", s:3},{t:"Menutup mata karena bukan wewenang langsung Anda.", s:2},{t:"Memanfaatkan situasi untuk kepentingan pribadi.", s:1}], ex:"Skor 5: melindungi masyarakat lewat pembinaan dan koordinasi — bukan sekadar meneruskan laporan."},
{id:"TKP-914", q:"Seorang warga yang buta huruf ingin mendaftarkan usaha kecilnya. Ia tidak bisa membaca formulir dan terlihat canggung di antara pemohon lain. Sikap Anda:", opts:[{t:"Membacakan dan menjelaskan setiap dokumen dengan sabar, lalu membantunya mengisi hingga selesai.", s:5},{t:"Membantu mengisikan formulirnya.", s:4},{t:"Memintanya kembali dengan pendamping yang bisa membaca.", s:3},{t:"Menolak melayani karena tidak bisa mengisi sendiri.", s:2},{t:"Mengejeknya di depan pemohon lain.", s:1}], ex:"Skor 5: empati penuh dan menjaga martabat — pelayanan inklusif tanpa mempermalukan."},
{id:"TKP-915", q:"Sistem OSS mengalami gangguan seharian sehingga tidak ada satu pun permohonan daring yang bisa diproses. Puluhan pemohon sudah antre di kantor. Sikap Anda:", opts:[{t:"Mengumumkan gangguan secara terbuka, membuka layanan manual darurat, dan mencatat antrean untuk diproses saat sistem pulih.", s:5},{t:"Meminta pemohon kembali besok dengan kepastian jadwal.", s:4},{t:"Menutup layanan hari itu sampai sistem pulih.", s:3},{t:"Menyalahkan pemerintah pusat di depan pemohon.", s:2},{t:"Memanfaatkan situasi untuk menawarkan 'jalur cepat' berbayar.", s:1}], ex:"Skor 5: adaptif dan transparan — solusi darurat plus komunikasi jujur menjaga kepercayaan publik."},
{id:"TKP-916", q:"Anda mencurigai oknum di loket sebelah melakukan pungutan liar kepada pemohon izin. Seorang warga bercerita sambil berbisik kepada Anda. Sikap Anda:", opts:[{t:"Mengumpulkan bukti awal dan melaporkannya melalui pimpinan atau kanal whistleblowing resmi.", s:5},{t:"Menegur oknum tersebut secara langsung.", s:4},{t:"Diam saja karena bukan urusan Anda.", s:3},{t:"Ikut-ikutan memungut karena tergiur.", s:2},{t:"Melindungi oknum tersebut dari pemeriksaan.", s:1}], ex:"Skor 5: berani dan prosedural — melawan pungli lewat jalur resmi dengan bukti, bukan main hakim sendiri."},
{id:"TKP-917", q:"Permohonan izin pemasangan reklame ditolak karena titiknya melanggar rencana tata ruang. Pemohon adalah pengusaha besar yang biasa beriklan di banyak kota. Sikap Anda:", opts:[{t:"Menolak sesuai aturan dengan penjelasan, lalu menawarkan titik-titik alternatif yang sesuai tata ruang.", s:5},{t:"Menolak sesuai aturan yang berlaku.", s:4},{t:"Meloloskan dengan catatan khusus.", s:3},{t:"Meloloskan karena segan pada pengusaha besar.", s:2},{t:"Meminta fee sebagai syarat pelolosan.", s:1}], ex:"Skor 5: tegas pada aturan, solutif bagi pemohon — besar-kecil pemohon diperlakukan sama."},
{id:"TKP-918", q:"Seorang pengusaha kecil mengeluhkan tarif resmi pengurusan izin yang menurutnya terlalu mahal bagi skala usahanya. Ia meminta keringanan. Sikap Anda:", opts:[{t:"Menjelaskan rincian tarif resmi serta menginformasikan skema keringanan atau pembebasan biaya bagi usaha mikro bila tersedia.", s:5},{t:"Menjelaskan bahwa tarif sudah ditetapkan dalam peraturan daerah.", s:4},{t:"Menyuruhnya membayar sesuai tarif tanpa penjelasan.", s:3},{t:"Mengabaikan keluhannya.", s:2},{t:"Menawarkan potongan tidak resmi dengan imbalan.", s:1}], ex:"Skor 5: transparan dan berpihak pada usaha kecil — memberi informasi hak yang mungkin tidak diketahui pemohon."},
{id:"TKP-919", q:"Kelompok tani di sebuah desa ingin membentuk usaha tani berbadan hukum agar bisa mengakses bantuan pemerintah, tetapi tidak memahami prosedurnya. Sikap Anda:", opts:[{t:"Memfasilitasi penyuluhan dan menghubungkan mereka dengan dinas pertanian serta dinas koperasi.", s:5},{t:"Memberikan informasi prosedur pembentukan badan usaha tani.", s:4},{t:"Mengarahkan mereka mencari informasi sendiri.", s:3},{t:"Menolak karena di luar tugas pokok Anda.", s:2},{t:"Mengabaikan permintaan mereka.", s:1}], ex:"Skor 5: proaktif memberdayakan — menghubungkan warga dengan sumber daya yang tepat lintas instansi."},
{id:"TKP-920", q:"Anda mendapati sejumlah izin operasional usaha akan kedaluwarsa bulan depan, tetapi para pemegang izin belum mengajukan perpanjangan. Sikap Anda:", opts:[{t:"Menghubungi para pemegang izin untuk mengingatkan dan memudahkan proses perpanjangannya.", s:5},{t:"Mengingatkan saat mereka datang ke kantor.", s:4},{t:"Membiarkannya karena itu tanggung jawab masing-masing.", s:3},{t:"Membiarkan kedaluwarsa agar bisa mengenakan denda.", s:2},{t:"Mempersulit perpanjangan agar mereka membayar lebih.", s:1}], ex:"Skor 5: pelayanan antisipatif — mencegah masalah sebelum terjadi, bukan menunggu pelanggaran."},
{id:"TKP-921", q:"Kelompok tani mengajukan bantuan alat mesin pertanian (alsintan) ke dinas. Proposal mereka belum lengkap dan musim tanam tinggal sebulan. Sikap Anda:", opts:[{t:"Membantu melengkapi proposal, mengusulkannya dengan kriteria transparan, dan berkoordinasi dengan dinas pertanian.", s:5},{t:"Meneruskan usulan mereka ke dinas terkait.", s:4},{t:"Menyuruh mereka melengkapi proposal sendiri.", s:3},{t:"Menolak karena berkas tidak lengkap.", s:2},{t:"Meminta bagian dari bantuan sebagai syarat pengurusan.", s:1}], ex:"Skor 5: fasilitatif dan transparan — membantu warga memenuhi syarat, bukan menjadikannya alasan penolakan."},
{id:"TKP-922", q:"Program PTSL (pendaftaran tanah sistematis lengkap) akan dilaksanakan di desa Anda bertugas. Banyak warga belum paham manfaat sertifikat tanah. Sikap Anda:", opts:[{t:"Aktif menyosialisasikan manfaatnya, mendampingi proses pengukuran, dan memastikan warga memahami setiap tahapannya.", s:5},{t:"Melaksanakan program sesuai jadwal yang ditentukan.", s:4},{t:"Mengerjakan seadanya mengikuti alur yang ada.", s:3},{t:"Mendahulukan warga yang memberi imbalan.", s:2},{t:"Melakukan pungutan liar dalam prosesnya.", s:1}], ex:"Skor 5: proaktif mengedukasi — kepastian hukum tanah hanya tercapai bila warga paham dan terlibat."},
{id:"TKP-923", q:"Terjadi ketegangan antara warga desa dan sebuah perusahaan perkebunan terkait lahan yang diklaim kedua belah pihak. Warga meminta pemerintah daerah memfasilitasi penyelesaian. Sikap Anda:", opts:[{t:"Memfasilitasi musyawarah dengan melibatkan semua pihak dan mendokumentasikan setiap kesepakatan secara resmi.", s:5},{t:"Melakukan mediasi secara netral antara kedua pihak.", s:4},{t:"Menyerahkan sepenuhnya kepada aparat keamanan.", s:3},{t:"Membela perusahaan karena dianggap membuka lapangan kerja.", s:2},{t:"Menerima suap dari salah satu pihak.", s:1}], ex:"Skor 5: fasilitator netral yang tuntas — musyawarah inklusif plus dokumentasi resmi mencegah konflik berulang."},
{id:"TKP-924", q:"Seorang pemohon izin tidak puas dengan hasil survei lapangan yang menyatakan lahannya tidak memenuhi syarat teknis. Ia menuntut survei ulang. Sikap Anda:", opts:[{t:"Menjelaskan hasil survei secara terbuka serta menginformasikan hak dan prosedur pengajuan keberatan atau survei ulang.", s:5},{t:"Menjelaskan hasil survei apa adanya.", s:4},{t:"Menyuruhnya menerima hasil tersebut.", s:3},{t:"Membentaknya karena dianggap tidak menghargai kerja petugas.", s:2},{t:"Mengubah hasil survei karena tertekan.", s:1}], ex:"Skor 5: transparan dan akuntabel — membuka mekanisme keberatan resmi menunjukkan integritas proses."},
{id:"TKP-925", q:"Mal pelayanan publik di daerah Anda sepi pengunjung padahal fasilitasnya bagus. Pimpinan meminta masukan untuk meningkatkan kunjungan. Sikap Anda:", opts:[{t:"Mengusulkan evaluasi layanan, promosi ke masyarakat, dan program jemput bola ke desa-desa.", s:5},{t:"Melaporkan kondisi tersebut kepada pimpinan.", s:4},{t:"Membiarkannya karena bukan wewenang Anda.", s:3},{t:"Menyalahkan warga yang tidak memanfaatkan fasilitas.", s:2},{t:"Mengusulkan mal ditutup saja.", s:1}], ex:"Skor 5: inovatif dan berorientasi hasil — mencari akar masalah dan menawarkan solusi konkret."},
{id:"TKP-926", q:"Melalui kanal LAPOR, seorang warga melaporkan dugaan pungutan liar di pos retribusi objek wisata. Identitas pelapor dilindungi sistem. Sikap Anda:", opts:[{t:"Segera menindaklanjuti, melakukan investigasi internal, dan memberi kabar perkembangan kepada pelapor.", s:5},{t:"Meneruskan laporan tersebut kepada atasan.", s:4},{t:"Mengarsipkan laporan tanpa tindak lanjut.", s:3},{t:"Mengabaikan laporan tersebut.", s:2},{t:"Membocorkan identitas pelapor kepada terlapor.", s:1}], ex:"Skor 5: responsif dan melindungi — menindaklanjuti cepat sambil menjaga keamanan pelapor."},
{id:"TKP-927", q:"Seorang investor menanyakan ketersediaan lahan di kawasan industri beserta data infrastruktur pendukungnya. Data yang Anda miliki belum diperbarui setahun terakhir. Sikap Anda:", opts:[{t:"Memperbarui dan memverifikasi data terlebih dahulu, lalu menyajikannya akurat sambil mendampingi survei lokasi.", s:5},{t:"Memberikan data yang ada disertai penjelasan.", s:4},{t:"Mengarahkannya mencari data sendiri.", s:3},{t:"Memberikan data lama apa adanya tanpa verifikasi.", s:2},{t:"Meminta komisi atas informasi tersebut.", s:1}], ex:"Skor 5: akurat dan profesional — data investasi menyangkut kepercayaan, harus valid sebelum diserahkan."},
{id:"TKP-928", q:"Sejumlah UMKM binaan ingin mengikuti pameran dagang tingkat provinsi tetapi terkendala biaya dan prosedur pendaftaran. Sikap Anda:", opts:[{t:"Memfasilitasi proses kurasi, membantu pendaftaran, dan mengupayakan dukungan promosi bagi mereka.", s:5},{t:"Menginformasikan jadwal dan syarat pameran.", s:4},{t:"Mengarahkan mereka mendaftar mandiri.", s:3},{t:"Menolak membantu karena keterbatasan anggaran.", s:2},{t:"Memungut biaya tidak resmi untuk keikutsertaan.", s:1}], ex:"Skor 5: aktif membuka akses pasar — pendampingan nyata bagi UMKM naik kelas."},
{id:"TKP-929", q:"Seorang juru parkir menolak membayar retribusi parkir resmi dan malah memungut tarif sendiri dari pengunjung. Sikap Anda:", opts:[{t:"Menegakkan aturan secara humanis, membinanya, dan menawarkan skema menjadi juru parkir resmi.", s:5},{t:"Menegakkan aturan sesuai ketentuan yang berlaku.", s:4},{t:"Membiarkannya karena kasihan.", s:3},{t:"Membentaknya di depan umum.", s:2},{t:"Menerima setoran darinya agar dibiarkan beroperasi.", s:1}], ex:"Skor 5: tegas namun humanis — penegakan hukum dibarengi solusi mata pencaharian."},
{id:"TKP-930", q:"Permohonan izin trayek angkutan umum harus diverifikasi kelayakan armadanya. Pemilik armada meminta proses dipercepat karena armadanya sudah beroperasi. Sikap Anda:", opts:[{t:"Memverifikasi kelayakan dan keselamatan armada secara tertib tanpa terpengaruh desakan.", s:5},{t:"Memverifikasi sesuai SOP yang berlaku.", s:4},{t:"Meloloskan cepat karena armada sudah beroperasi.", s:3},{t:"Mempersulit prosesnya dengan sengaja.", s:2},{t:"Meminta fee percepatan.", s:1}], ex:"Skor 5: keselamatan publik di atas desakan — verifikasi tertib melindungi penumpang."},
{id:"TKP-931", q:"Nelayan tradisional ingin mengurus izin kapal penangkap ikan tetapi terbentur persyaratan dokumen yang rumit. Hasil tangkapan adalah satu-satunya mata pencaharian mereka. Sikap Anda:", opts:[{t:"Menyederhanakan alur sesuai ketentuan, mendampingi pengurusan, dan berkoordinasi dengan dinas kelautan.", s:5},{t:"Menjelaskan persyaratan dengan bahasa yang mudah dipahami.", s:4},{t:"Menyuruh mereka melengkapi sendiri semua dokumen.", s:3},{t:"Menolak karena dokumen tidak lengkap.", s:2},{t:"Meminta imbalan untuk mempermudah.", s:1}], ex:"Skor 5: keberpihakan pada kelompok rentan — menyederhanakan dalam koridor aturan plus pendampingan."},
{id:"TKP-932", q:"Penertiban pedagang kaki lima di kawasan protokol menimbulkan protes karena mereka kehilangan tempat berjualan. Sikap Anda:", opts:[{t:"Menawarkan solusi relokasi ke lokasi binaan yang layak serta memfasilitasi perizinannya.", s:5},{t:"Menjelaskan alasan penertiban sesuai aturan.", s:4},{t:"Tetap menertibkan tanpa solusi.", s:3},{t:"Membiarkan mereka kembali berjualan liar.", s:2},{t:"Meminta uang damai agar tidak ditertibkan.", s:1}], ex:"Skor 5: penertiban berkeadilan — ketertiban kota dijaga tanpa mematikan mata pencaharian."},
{id:"TKP-933", q:"Koperasi wanita di desa Anda berjalan baik tetapi kesulitan mengakses permodalan untuk mengembangkan usaha anggotanya. Sikap Anda:", opts:[{t:"Memfasilitasi akses permodalan lewat program pemerintah dan mendampingi penguatan kelembagaannya.", s:5},{t:"Memberikan informasi program permodalan yang tersedia.", s:4},{t:"Mengarahkan mereka ke bank sendiri.", s:3},{t:"Mengabaikan karena skala usahanya kecil.", s:2},{t:"Memanfaatkan koperasi untuk kepentingan pribadi.", s:1}], ex:"Skor 5: pemberdayaan aktif — menghubungkan dengan sumber daya plus penguatan kelembagaan."},
{id:"TKP-934", q:"Seorang warga mengajukan permohonan informasi publik mengenai penggunaan anggaran program bantuan UMKM. Ia bersikeras ingin data rinci. Sikap Anda:", opts:[{t:"Melayani melalui mekanisme PPID resmi dengan data yang terbuka sesuai ketentuan, serta menjelaskan yang dikecualikan.", s:5},{t:"Memberikan informasi sesuai prosedur yang berlaku.", s:4},{t:"Menyuruhnya bertanya langsung ke pimpinan.", s:3},{t:"Menolak dengan alasan data rahasia.", s:2},{t:"Memberikan data yang sudah dimanipulasi.", s:1}], ex:"Skor 5: transparan dan prosedural — keterbukaan informasi publik dijalankan lewat mekanisme resmi."},
{id:"TKP-935", q:"Dua ahli waris bersengketa atas sebidang tanah dan sama-sama meminta surat keterangan dari kelurahan untuk menguatkan klaimnya. Sikap Anda:", opts:[{t:"Bersikap netral, menjelaskan prosedur resmi, dan mengarahkan penyelesaian ke BPN atau pengadilan.", s:5},{t:"Mengarahkan keduanya ke jalur hukum yang berlaku.", s:4},{t:"Memberi surat keterangan kepada yang datang lebih dulu.", s:3},{t:"Membela salah satu pihak yang Anda kenal.", s:2},{t:"Memberi surat kepada yang berani membayar.", s:1}], ex:"Skor 5: netralitas penuh — aparat tidak boleh menjadi alat salah satu pihak yang bersengketa."},
{id:"TKP-936", q:"Permohonan izin operasional sebuah apotek perlu diverifikasi keberadaan apoteker penanggung jawabnya. Pemilik apotek mengaku apotekernya sering tidak di tempat. Sikap Anda:", opts:[{t:"Memverifikasi ketat sesuai standar kefarmasian dan menunda izin hingga syarat terpenuhi.", s:5},{t:"Memverifikasi sesuai SOP.", s:4},{t:"Meloloskan dengan peringatan lisan.", s:3},{t:"Meloloskan karena kasihan pada pemilik.", s:2},{t:"Meminta imbalan untuk meloloskan.", s:1}], ex:"Skor 5: standar kesehatan tidak bisa ditawar — verifikasi ketat melindungi masyarakat."},
{id:"TKP-937", q:"Sejumlah pelaku usaha mengeluhkan waktu pengurusan izin yang melebihi janji layanan dalam SOP. Keluhan ini berulang setiap bulan. Sikap Anda:", opts:[{t:"Mengevaluasi akar keterlambatan, mengusulkan perbaikan SOP, dan melaporkan hasilnya kepada pimpinan.", s:5},{t:"Melaporkan keluhan tersebut kepada atasan.", s:4},{t:"Meminta pemohon bersabar.", s:3},{t:"Menyalahkan pemohon yang berkasnya tidak lengkap.", s:2},{t:"Menawarkan percepatan berbayar.", s:1}], ex:"Skor 5: perbaikan sistemik — tidak berhenti pada keluhan, tapi memperbaiki prosesnya."},
{id:"TKP-938", q:"Sebuah perusahaan besar menawarkan dana CSR untuk program pemberdayaan UMKM di daerah Anda. Sikap Anda:", opts:[{t:"Menyinergikan dana CSR dengan program resmi secara transparan dan terdokumentasi.", s:5},{t:"Menerima dan menyalurkan sesuai peruntukannya.", s:4},{t:"Meneruskan ke pimpinan tanpa terlibat.", s:3},{t:"Menolak karena merepotkan administrasi.", s:2},{t:"Mengelola sendiri tanpa pencatatan.", s:1}], ex:"Skor 5: sinergi yang akuntabel — dana pihak ketiga dikelola transparan dalam program resmi."},
{id:"TKP-939", q:"Pemilik restoran mengaku tidak tahu bahwa usahanya wajib memungut pajak restoran dari pelanggan. Ia khawatir terkena sanksi. Sikap Anda:", opts:[{t:"Mengedukasi kewajibannya, menjelaskan cara pemungutan dan penyetoran, serta membantunya mendaftar sebagai wajib pajak.", s:5},{t:"Menjelaskan kewajiban pajak sesuai peraturan.", s:4},{t:"Menyuruhnya membaca peraturan sendiri.", s:3},{t:"Langsung mengenakan sanksi maksimal.", s:2},{t:"Membebaskannya dari kewajiban dengan imbalan.", s:1}], ex:"Skor 5: edukatif sebelum represif — kepatuhan dibangun lewat pemahaman, bukan ancaman."},
{id:"TKP-940", q:"Permohonan izin gudang penyimpanan diajukan di kawasan yang menurut rencana tata ruang diperuntukkan bagi permukiman. Pemohon sudah telanjur menyewa lahan. Sikap Anda:", opts:[{t:"Menolak sesuai tata ruang dengan penjelasan, serta membantu mencarikan alternatif lokasi yang sesuai zonasi.", s:5},{t:"Menolak sesuai ketentuan tata ruang.", s:4},{t:"Meloloskan dengan dispensasi khusus.", s:3},{t:"Meloloskan karena pemohon sudah rugi menyewa lahan.", s:2},{t:"Meminta kompensasi untuk meloloskan.", s:1}], ex:"Skor 5: tata ruang ditegakkan, pemohon tetap dibantu — ketegasan plus solusi."},
{id:"TKP-941", q:"Peternak ayam di desa Anda kesulitan mendapatkan izin usaha peternakan karena lokasinya dekat permukiman dan dikhawatirkan menimbulkan bau. Sikap Anda:", opts:[{t:"Memfasilitasi kajian teknis bersama dinas peternakan dan menawarkan solusi lokasi atau teknologi yang memenuhi syarat.", s:5},{t:"Menjelaskan syarat teknis yang harus dipenuhi.", s:4},{t:"Menolak mentah-mentah permohonannya.", s:3},{t:"Meloloskan diam-diam karena kasihan.", s:2},{t:"Meminta imbalan untuk meloloskan.", s:1}], ex:"Skor 5: solutif berbasis kajian — kepentingan usaha dan kenyamanan warga dijembatani lewat solusi teknis."},
{id:"TKP-942", q:"Seorang warga melaporkan sertifikat tanahnya hilang dan membutuhkan surat keterangan untuk pengurusan pengganti di BPN. Ia tampak cemas. Sikap Anda:", opts:[{t:"Melayani dengan cepat, menjelaskan prosedur pengganti, dan membantu kelengkapan persyaratannya.", s:5},{t:"Membuatkan surat keterangan sesuai prosedur.", s:4},{t:"Menyuruhnya mengurus sendiri ke BPN.", s:3},{t:"Menunda-nunda pembuatannya.", s:2},{t:"Meminta biaya di luar ketentuan.", s:1}], ex:"Skor 5: cepat, jelas, dan menenangkan — pelayanan prima untuk warga yang sedang kesulitan."},
{id:"TKP-943", q:"Pengelola kawasan wisata mengeluhkan pungutan retribusi yang tidak jelas dasarnya oleh oknum di pintu masuk, sehingga pengunjung komplain. Sikap Anda:", opts:[{t:"Menertibkan pungutan sesuai tarif resmi, memasang papan tarif transparan, dan menindak oknum yang bermain.", s:5},{t:"Menegakkan tarif resmi sesuai ketentuan.", s:4},{t:"Mengimbau pengelola bersabar.", s:3},{t:"Membiarkan karena sudah lama begitu.", s:2},{t:"Ikut menerima bagian dari pungutan.", s:1}], ex:"Skor 5: transparansi tarif plus penindakan — kepercayaan wisatawan dijaga lewat kepastian."},
{id:"TKP-944", q:"Seorang eksportir produk pertanian menanyakan prosedur perizinan ekspor dan sertifikasi yang dibutuhkan. Ia baru pertama kali mengekspor. Sikap Anda:", opts:[{t:"Memfasilitasi dengan penjelasan alur lengkap dan menghubungkannya dengan instansi karantina serta bea cukai.", s:5},{t:"Memberikan informasi prosedur yang diketahui.", s:4},{t:"Mengarahkannya mencari sendiri informasinya.", s:3},{t:"Menolak karena bukan wewenang dinas Anda.", s:2},{t:"Meminta fee jasa pengurusan.", s:1}], ex:"Skor 5: fasilitasi lintas instansi — membantu pelaku usaha menembus pasar ekspor."},
{id:"TKP-945", q:"Permohonan izin praktik bidan mandiri perlu diverifikasi kelengkapan surat tanda registrasi dan tempat praktiknya. Sikap Anda:", opts:[{t:"Memverifikasi teliti sesuai standar pelayanan kesehatan dan memberi arahan perbaikan bila ada kekurangan.", s:5},{t:"Memverifikasi sesuai SOP yang berlaku.", s:4},{t:"Meloloskan cepat tanpa verifikasi lapangan.", s:3},{t:"Mempersulit karena tidak kenal pemohon.", s:2},{t:"Meminta imbalan percepatan.", s:1}], ex:"Skor 5: standar keselamatan pasien dijaga lewat verifikasi teliti plus pembinaan."},
{id:"TKP-946", q:"Warga yang lahannya terdampak proyek jalan daerah menuntut ganti rugi yang layak dan transparan. Mereka khawatir nilainya ditentukan sepihak. Sikap Anda:", opts:[{t:"Memfasilitasi musyawarah ganti rugi yang transparan dengan melibatkan penilai independen dan mendokumentasikan kesepakatan.", s:5},{t:"Mengarahkan ke tim pengadaan tanah resmi.", s:4},{t:"Menyuruh mereka menerima tawaran yang ada.", s:3},{t:"Mengabaikan tuntutan mereka.", s:2},{t:"Memotong nilai ganti rugi untuk keuntungan pribadi.", s:1}], ex:"Skor 5: keadilan prosedural — transparansi dan penilai independen melindungi hak warga."},
{id:"TKP-947", q:"Banyak warga desa kesulitan datang ke kota untuk mengurus perizinan karena jarak dan biaya transportasi. Sikap Anda:", opts:[{t:"Mengusulkan dan melaksanakan layanan jemput bola atau keliling ke desa-desa secara berkala.", s:5},{t:"Memberikan informasi agar mereka bisa mengurus daring.", s:4},{t:"Menyarankan mereka datang berkelompok agar hemat.", s:3},{t:"Membiarkannya karena itu risiko tinggal di desa.", s:2},{t:"Menawarkan pengurusan lewat calo.", s:1}], ex:"Skor 5: inovasi menjangkau — negara hadir ke warga, bukan sebaliknya."},
{id:"TKP-948", q:"Pemerintah meluncurkan program pembebasan biaya pengurusan izin bagi usaha mikro. Banyak pelaku usaha mikro belum mengetahuinya. Sikap Anda:", opts:[{t:"Aktif menyosialisasikan program ke sentra-sentra usaha mikro dan memfasilitasi pendaftarannya.", s:5},{t:"Menempelkan pengumuman di papan informasi kantor.", s:4},{t:"Menunggu warga bertanya sendiri.", s:3},{t:"Menyembunyikan informasi agar kuota tidak cepat habis.", s:2},{t:"Memungut biaya meski programnya gratis.", s:1}], ex:"Skor 5: proaktif menyebarkan hak warga — program baik harus sampai ke sasaran."},
{id:"TKP-949", q:"Terjadi konflik antara penambang rakyat dan perusahaan pemegang izin tambang yang wilayahnya tumpang tindih. Situasi di lapangan memanas. Sikap Anda:", opts:[{t:"Memfasilitasi dialog semua pihak, berkoordinasi dengan aparat dan dinas ESDM, serta mengedepankan keselamatan.", s:5},{t:"Melaporkan dan berkoordinasi dengan instansi berwenang.", s:4},{t:"Menyerahkan sepenuhnya kepada aparat keamanan.", s:3},{t:"Membela perusahaan karena berizin resmi.", s:2},{t:"Menerima suap untuk memihak.", s:1}], ex:"Skor 5: fasilitasi menyeluruh — dialog, koordinasi, dan keselamatan diutamakan."},
{id:"TKP-950", q:"Hasil survei kepuasan masyarakat (IKM) terhadap layanan perizinan di unit Anda menurun dua periode berturut-turut. Pimpinan meminta analisis. Sikap Anda:", opts:[{t:"Menganalisis akar masalah dari data survei, menyusun rencana perbaikan konkret, dan memaparkannya kepada pimpinan.", s:5},{t:"Melaporkan hasil survei apa adanya.", s:4},{t:"Menganggap survei tidak mencerminkan kondisi nyata.", s:3},{t:"Menyalahkan responden yang tidak objektif.", s:2},{t:"Memalsukan data survei berikutnya agar terlihat baik.", s:1}], ex:"Skor 5: data dijadikan dasar perbaikan — akuntabel dan berorientasi hasil."},
{id:"TKP-951", q:"Seorang pemohon izin menyelipkan amplop berisi uang dan berbisik agar berkasnya didahulukan. Tidak ada yang melihat kejadian itu. Sikap Anda:", opts:[{t:"Menolak tegas, mengembalikan amplop, menjelaskan bahwa semua dilayani sesuai antrean, dan tetap memproses berkasnya normal.", s:5},{t:"Menolak amplop tersebut dengan sopan.", s:4},{t:"Menerima amplop tetapi tetap memproses sesuai antrean.", s:3},{t:"Menerima dan mendahulukan berkasnya.", s:2},{t:"Meminta tambahan karena risikonya besar.", s:1}], ex:"Skor 5: integritas penuh — menolak, menjelaskan, dan tetap melayani secara profesional."},
{id:"TKP-952", q:"Atasan Anda meminta meloloskan berkas perizinan milik kerabatnya yang belum lengkap, dengan alasan 'nanti dilengkapi menyusul'. Sikap Anda:", opts:[{t:"Menolak secara halus, menjelaskan aturan yang mengikat semua pihak, dan menawarkan bantuan melengkapi berkasnya.", s:5},{t:"Menolak permintaan tersebut.", s:4},{t:"Meloloskan sebagian prosesnya saja.", s:3},{t:"Meloloskan karena perintah atasan.", s:2},{t:"Meloloskan dan menutupi kekurangannya.", s:1}], ex:"Skor 5: berani benar pada atasan — aturan ditegakkan dengan cara santun plus solusi."},
{id:"TKP-953", q:"Anda menemukan selisih antara setoran retribusi yang tercatat dan uang tunai di brankas. Selisihnya cukup besar dan belum jelas penyebabnya. Sikap Anda:", opts:[{t:"Melaporkan temuan, menelusuri penyebabnya bersama tim, dan mengusulkan perbaikan sistem pencatatan.", s:5},{t:"Melaporkan temuan kepada atasan.", s:4},{t:"Diam dan berharap tidak ada yang tahu.", s:3},{t:"Menutupi selisih dengan memanipulasi catatan.", s:2},{t:"Mengambil selisihnya untuk pribadi.", s:1}], ex:"Skor 5: akuntabel dan solutif — lapor, telusur, dan perbaiki sistem agar tidak terulang."},
{id:"TKP-954", q:"Rekan sejawat mengajak Anda bermain gim di ponsel saat jam pelayanan padahal antrean pemohon sedang ramai. Sikap Anda:", opts:[{t:"Menolak ajakan, mengingatkannya, dan kembali fokus melayani pemohon.", s:5},{t:"Menolak ajakan tersebut.", s:4},{t:"Ikut bermain sebentar saja.", s:3},{t:"Ikut bermain sampai antrean sepi.", s:2},{t:"Mengajak rekan lain ikut bermain.", s:1}], ex:"Skor 5: disiplin dan berani mengingatkan — kepentingan pemohon di atas kesenangan pribadi."},
{id:"TKP-955", q:"Anda mengetahui data pribadi wajib pajak bocor dan beredar di pihak yang tidak berwenang. Sumber kebocoran belum jelas. Sikap Anda:", opts:[{t:"Melaporkan insiden, mengamankan akses data, dan mengevaluasi sistem keamanannya.", s:5},{t:"Melaporkan kejadian kepada atasan.", s:4},{t:"Diam karena takut disalahkan.", s:3},{t:"Menutupi kejadian tersebut.", s:2},{t:"Memanfaatkan data itu untuk keuntungan pribadi.", s:1}], ex:"Skor 5: melindungi data warga lewat respons cepat dan perbaikan sistem."},
{id:"TKP-956", q:"Anggota keluarga Anda mengajukan izin usaha dan kebetulan berkasnya masuk ke loket tempat Anda bertugas. Sikap Anda:", opts:[{t:"Mengalihkan penanganannya ke rekan lain untuk menghindari konflik kepentingan.", s:5},{t:"Tetap melayani tetapi secara transparan dan sesuai prosedur.", s:4},{t:"Melayani seperti pemohon biasa.", s:3},{t:"Mendahulukan berkasnya dari antrean.", s:2},{t:"Meloloskan secepatnya tanpa verifikasi.", s:1}], ex:"Skor 5: menghindari konflik kepentingan secara aktif — integritas di atas kedekatan pribadi."},
{id:"TKP-957", q:"Akibat kesalahan input Anda, data seorang pemohon izin tercatat keliru sehingga prosesnya tertunda. Pemohon belum menyadarinya. Sikap Anda:", opts:[{t:"Mengakui kesalahan, segera memperbaikinya, meminta maaf, dan memastikan tidak terulang.", s:5},{t:"Segera memperbaiki data yang keliru.", s:4},{t:"Menyalahkan sistem yang error.", s:3},{t:"Menyalahkan pemohon yang datanya tidak jelas.", s:2},{t:"Menutupi kesalahan tersebut.", s:1}], ex:"Skor 5: akuntabel penuh — mengakui, memperbaiki, meminta maaf, dan mencegah."},
{id:"TKP-958", q:"Sebuah perusahaan yang perizinannya Anda awasi menawarkan pekerjaan sampingan dengan bayaran besar. Sikap Anda:", opts:[{t:"Menolak karena berpotensi menimbulkan konflik kepentingan dalam pengawasan.", s:5},{t:"Menolak tawaran tersebut.", s:4},{t:"Menerima diam-diam di luar jam kerja.", s:3},{t:"Menerima tawaran itu.", s:2},{t:"Memanfaatkan jabatan untuk mendapatkan posisi lebih tinggi.", s:1}], ex:"Skor 5: menjaga independensi pengawasan — konflik kepentingan ditolak sejak awal."},
{id:"TKP-959", q:"Tim sukses seorang calon kepala daerah meminta data pelaku usaha untuk kepentingan kampanye. Mereka menjanjikan imbalan. Sikap Anda:", opts:[{t:"Menolak tegas dan menjelaskan kewajiban netralitas ASN dalam pemilu.", s:5},{t:"Menolak permintaan tersebut.", s:4},{t:"Memberikan sebagian data saja.", s:3},{t:"Memberikan data yang diminta.", s:2},{t:"Ikut membantu kampanyenya.", s:1}], ex:"Skor 5: netralitas ASN dijaga mutlak — data negara tidak untuk kepentingan politik."},
{id:"TKP-960", q:"Anda memergoki rekan kerja memalsukan tanda tangan pejabat pada dokumen perizinan. Sikap Anda:", opts:[{t:"Menegurnya dan melaporkan pelanggaran sesuai aturan yang berlaku.", s:5},{t:"Melaporkan kejadian tersebut.", s:4},{t:"Diam karena tidak ingin bermasalah dengan rekan.", s:3},{t:"Ikut membantu memalsukan.", s:2},{t:"Melindungi rekan dari pemeriksaan.", s:1}], ex:"Skor 5: berani menegur dan melapor — pemalsuan dokumen adalah pelanggaran serius."},
{id:"TKP-961", q:"Anda datang terlambat 30 menit padahal antrean pemohon izin sudah memanjang di depan loket. Beberapa pemohon tampak kesal. Sikap Anda:", opts:[{t:"Meminta maaf, segera melayani dengan sigap, dan berkomitmen memperbaiki kedisiplinan.", s:5},{t:"Langsung bekerja melayani tanpa banyak bicara.", s:4},{t:"Bersikap santai seolah tidak terjadi apa-apa.", s:3},{t:"Menyalahkan kemacetan setiap kali terlambat.", s:2},{t:"Tidak masuk sekalian dan membiarkan loket kosong.", s:1}], ex:"Skor 5: mengakui, meminta maaf, dan memperbaiki — disiplin adalah wajah pelayanan."},
{id:"TKP-962", q:"Sistem OSS diperbarui ke versi baru dan Anda belum memahaminya, padahal pemohon sudah antre menanyakan fitur barunya. Sikap Anda:", opts:[{t:"Belajar mandiri, mengikuti pelatihan, dan bertanya kepada yang lebih paham hingga menguasai.", s:5},{t:"Mempelajari sistem baru tersebut.", s:4},{t:"Meminta rekan mengerjakan bagian yang sulit.", s:3},{t:"Menolak menggunakan sistem baru.", s:2},{t:"Menyebarkan kabar bahwa sistem baru menyusahkan.", s:1}], ex:"Skor 5: kompeten dan adaptif — kemauan belajar adalah tanggung jawab profesional."},
{id:"TKP-963", q:"Anda menemukan tumpukan berkas perpanjangan izin yang kedaluwarsa dan belum diproses selama berbulan-bulan. Sikap Anda:", opts:[{t:"Menginventarisasi, menghubungi para pemohon, dan mempercepat penyelesaiannya.", s:5},{t:"Melaporkan temuan kepada pimpinan.", s:4},{t:"Membiarkannya karena bukan Anda yang menumpuk.", s:3},{t:"Membuang berkas-berkas lama itu.", s:2},{t:"Memanfaatkannya untuk memungut biaya percepatan.", s:1}], ex:"Skor 5: proaktif membereskan warisan masalah — bukan mencari siapa yang salah."},
{id:"TKP-964", q:"Atasan mempresentasikan ide perbaikan layanan yang sebenarnya berasal dari usulan Anda, tanpa menyebut nama Anda. Sikap Anda:", opts:[{t:"Tetap profesional, mendukung implementasi ide, dan mendokumentasikan kontribusi untuk ke depan.", s:5},{t:"Menyampaikan keberatan secara baik-baik kepada atasan.", s:4},{t:"Diam saja meski kecewa.", s:3},{t:"Memprotes keras di depan forum.", s:2},{t:"Menyabotase pelaksanaan ide tersebut.", s:1}], ex:"Skor 5: dewasa dan berorientasi hasil — ide yang bermanfaat tetap didukung meski kredit hilang."},
{id:"TKP-965", q:"Seorang vendor menawarkan paket perjalanan sebagai 'bonus' agar perusahaannya dimenangkan dalam pengadaan di dinas Anda. Sikap Anda:", opts:[{t:"Menolak dan melaporkan gratifikasi sesuai ketentuan.", s:5},{t:"Menolak tawaran tersebut.", s:4},{t:"Menerima tetapi diam-diam.", s:3},{t:"Menerima tawaran itu.", s:2},{t:"Meminta bonus yang lebih besar.", s:1}], ex:"Skor 5: gratifikasi ditolak dan dilaporkan — integritas pengadaan dijaga."},
{id:"TKP-966", q:"Rekan kerja sering meninggalkan kantor di jam kerja untuk urusan pribadi sehingga bebannya menumpuk pada Anda. Sikap Anda:", opts:[{t:"Mengingatkannya secara baik-baik dan melaporkannya bila kebiasaan itu berlanjut.", s:5},{t:"Mengingatkannya.", s:4},{t:"Diam dan menanggung bebannya.", s:3},{t:"Ikut-ikutan keluar kantor.", s:2},{t:"Memanfaatkan ketidakhadirannya untuk bermalas-malasan.", s:1}], ex:"Skor 5: menegur dengan santun plus eskalasi prosedural bila tidak berubah."},
{id:"TKP-967", q:"Seorang pejabat menelepon meminta berkas perizinannya didahulukan dari antrean dengan alasan kesibukannya. Sikap Anda:", opts:[{t:"Melayani sesuai SOP dan menjelaskan bahwa semua pemohon diperlakukan sama.", s:5},{t:"Menolak secara halus.", s:4},{t:"Mendahulukan diam-diam.", s:3},{t:"Mendahulukan secara terbuka.", s:2},{t:"Menjadikannya langganan jalur khusus berbayar.", s:1}], ex:"Skor 5: kesetaraan layanan — jabatan tidak memberi hak antrean khusus."},
{id:"TKP-968", q:"Anda menyadari ada kesalahan perhitungan pajak daerah yang merugikan kas daerah dalam jumlah besar. Kesalahan itu berasal dari unit Anda. Sikap Anda:", opts:[{t:"Mengakui, mengoreksi perhitungan, memastikan kekurangan disetor, dan mengevaluasi prosedurnya.", s:5},{t:"Melaporkan kesalahan kepada pimpinan.", s:4},{t:"Diam berharap tidak ketahuan.", s:3},{t:"Menutupi dengan memanipulasi laporan.", s:2},{t:"Menggelapkan selisihnya.", s:1}], ex:"Skor 5: akuntabel penuh atas uang negara — koreksi, setoran, dan perbaikan sistem."},
{id:"TKP-969", q:"Seorang wartawan meminta dokumen tender proyek yang bersifat rahasia dengan imbalan pemberitaan positif. Sikap Anda:", opts:[{t:"Menolak dan mengarahkannya ke mekanisme PPID atau prosedur resmi.", s:5},{t:"Menolak permintaan tersebut.", s:4},{t:"Memberikan bocoran sebagian.", s:3},{t:"Memberikan dokumen yang diminta.", s:2},{t:"Menjual dokumen tersebut.", s:1}], ex:"Skor 5: informasi publik punya jalurnya — menolak suap pemberitaan dan mengarahkan ke prosedur."},
{id:"TKP-970", q:"Sekelompok orang mengintimidasi agar Anda meloloskan izin usaha yang tidak memenuhi syarat, dengan ancaman akan membuat keributan. Sikap Anda:", opts:[{t:"Tetap teguh pada aturan, tidak terpengaruh intimidasi, dan melaporkan ancaman tersebut.", s:5},{t:"Menolak meloloskan izinnya.", s:4},{t:"Menunda keputusan untuk menghindari konflik.", s:3},{t:"Meloloskan karena takut.", s:2},{t:"Bekerja sama dengan mereka.", s:1}], ex:"Skor 5: integritas tidak bisa diintimidasi — teguh plus melapor lewat jalur resmi."},
{id:"TKP-971", q:"Anda diminta menilai kinerja rekan sejawat yang kinerjanya buruk tetapi hubungannya dekat dengan Anda. Sikap Anda:", opts:[{t:"Menilai secara objektif berdasarkan fakta dan memberi masukan yang membangun.", s:5},{t:"Menilai objektif apa adanya.", s:4},{t:"Memberi nilai baik agar aman.", s:3},{t:"Memberi nilai buruk karena kesal.", s:2},{t:"Memanipulasi penilaian untuk menjatuhkannya.", s:1}], ex:"Skor 5: objektivitas di atas kedekatan — penilaian jujur plus pembinaan."},
{id:"TKP-972", q:"Pimpinan menugaskan Anda menangani verifikasi izin sektor perikanan, padahal latar belakang Anda bukan di bidang itu. Sikap Anda:", opts:[{t:"Menerima tugas, belajar cepat, dan meminta bimbingan dari yang berpengalaman.", s:5},{t:"Menerima dan mengerjakannya.", s:4},{t:"Menolak karena bukan kompetensi Anda.", s:3},{t:"Mengerjakan asal-asalan.", s:2},{t:"Melempar tugas ke rekan lain.", s:1}], ex:"Skor 5: adaptif dan bertanggung jawab — keterbatasan diatasi dengan belajar, bukan ditolak."},
{id:"TKP-973", q:"Layanan perizinan dinas Anda dikritik pedas oleh warga di media sosial dan unggahannya viral. Sikap Anda:", opts:[{t:"Menanggapi dengan santun, menindaklanjuti kritiknya, dan memperbaiki yang dikeluhkan.", s:5},{t:"Menanggapi kritik tersebut dengan baik.", s:4},{t:"Mengabaikan unggahan itu.", s:3},{t:"Membalas dengan nada emosional.", s:2},{t:"Menyerang balik akun pengkritik.", s:1}], ex:"Skor 5: kritik adalah masukan gratis — ditanggapi santun dan ditindaklanjuti nyata."},
{id:"TKP-974", q:"Anda sering lembur menyelesaikan tumpukan berkas perizinan tetapi uang lembur tidak kunjung dibayar. Sikap Anda:", opts:[{t:"Menyampaikan melalui jalur resmi dan tetap bekerja profesional.", s:5},{t:"Menyampaikan keluhan kepada atasan.", s:4},{t:"Diam tetapi bekerja dengan dongkol.", s:3},{t:"Menolak lembur berikutnya.", s:2},{t:"Mencuri waktu kerja sebagai ganti.", s:1}], ex:"Skor 5: menyalurkan aspirasi lewat jalur resmi tanpa mengorbankan profesionalisme."},
{id:"TKP-975", q:"Anda dimutasi ke bidang pelayanan yang sama sekali baru bagi Anda. Sikap Anda:", opts:[{t:"Beradaptasi cepat, mempelajari bidang baru, dan membangun relasi dengan tim.", s:5},{t:"Menjalani mutasi tersebut.", s:4},{t:"Memprotes keputusan mutasi.", s:3},{t:"Menolak mutasi.", s:2},{t:"Bekerja asal-asalan sebagai protes.", s:1}], ex:"Skor 5: adaptif dan positif — mutasi adalah amanah sekaligus kesempatan belajar."},
{id:"TKP-976", q:"Anda menemukan indikasi pungutan liar di pos retribusi objek wisata yang dikelola daerah. Oknumnya adalah senior Anda. Sikap Anda:", opts:[{t:"Mengumpulkan bukti dan melaporkannya melalui kanal resmi.", s:5},{t:"Melaporkan temuan tersebut.", s:4},{t:"Diam karena sungkan pada senior.", s:3},{t:"Ikut menikmati hasilnya.", s:2},{t:"Melindungi oknum dari pemeriksaan.", s:1}], ex:"Skor 5: kebenaran di atas senioritas — bukti dan jalur resmi, bukan sungkan."},
{id:"TKP-977", q:"Seorang pemohon tunarungu datang mengurus izin usaha kecilnya dan kesulitan berkomunikasi dengan petugas loket. Sikap Anda:", opts:[{t:"Melayaninya dengan sabar menggunakan bahasa tulisan atau alat bantu komunikasi hingga ia paham.", s:5},{t:"Melayaninya dengan baik dan sabar.", s:4},{t:"Melayaninya seperti biasa tanpa penyesuaian.", s:3},{t:"Menyuruhnya kembali dengan penerjemah.", s:2},{t:"Menolak melayani.", s:1}], ex:"Skor 5: pelayanan inklusif yang aktif menyesuaikan cara komunikasi."},
{id:"TKP-978", q:"Banjir melanda wilayah Anda dan kantor dijadikan posko darurat. Pelayanan perizinan lumpuh sementara. Sikap Anda:", opts:[{t:"Sigap membantu penanganan darurat dan berkoordinasi dengan tim penanggulangan bencana.", s:5},{t:"Membantu semampunya di posko.", s:4},{t:"Menunggu perintah atasan.", s:3},{t:"Pulang karena kantor tidak beroperasi.", s:2},{t:"Memanfaatkan bantuan bencana untuk pribadi.", s:1}], ex:"Skor 5: kemanusiaan di atas rutinitas — sigap dan terkoordinasi dalam darurat."},
{id:"TKP-979", q:"Anggaran kegiatan pemberdayaan UMKM dipotong sehingga banyak rencana harus disesuaikan. Sikap Anda:", opts:[{t:"Menyusun ulang prioritas secara efisien dan transparan agar program tetap berjalan.", s:5},{t:"Menyesuaikan kegiatan dengan anggaran yang ada.", s:4},{t:"Mengeluhkan pemotongan ke mana-mana.", s:3},{t:"Melakukan mark-up agar anggaran cukup.", s:2},{t:"Menggelapkan sisa anggaran.", s:1}], ex:"Skor 5: efisiensi dan transparansi — keterbatasan dijawab dengan prioritas, bukan akal-akalan."},
{id:"TKP-980", q:"Anda diminta menjadi saksi dalam kasus dugaan korupsi yang melibatkan rekan kerja Anda. Sikap Anda:", opts:[{t:"Bersaksi jujur sesuai fakta yang Anda ketahui.", s:5},{t:"Bersaksi apa adanya.", s:4},{t:"Menolak menjadi saksi.", s:3},{t:"Berbohong untuk melindunginya.", s:2},{t:"Membantu menghilangkan bukti.", s:1}], ex:"Skor 5: kejujuran di atas solidaritas semu — fakta disampaikan apa adanya."},
{id:"TKP-981", q:"Target Pendapatan Asli Daerah (PAD) dari sektor retribusi tidak tercapai tahun ini. Unit Anda ikut disorot. Sikap Anda:", opts:[{t:"Mengevaluasi penyebabnya, menyusun strategi baru, dan bekerja lebih giat mencapainya.", s:5},{t:"Mengevaluasi kinerja unit.", s:4},{t:"Menyalahkan kondisi ekonomi.", s:3},{t:"Memanipulasi data capaian.", s:2},{t:"Melakukan pungutan liar untuk menutup target.", s:1}], ex:"Skor 5: akuntabel dan solutif — evaluasi jujur plus strategi perbaikan."},
{id:"TKP-982", q:"Aplikasi pencatatan retribusi error saat Anda menginput data setoran penting. Data belum tersimpan. Sikap Anda:", opts:[{t:"Mengamankan data, mencatat manual sementara, dan melaporkan gangguan ke tim IT.", s:5},{t:"Melaporkan gangguan tersebut.", s:4},{t:"Mencoba input berulang-ulang.", s:3},{t:"Mengabaikan dan pulang.", s:2},{t:"Menghapus data agar tidak ketahuan.", s:1}], ex:"Skor 5: melindungi data negara — pengamanan, pencatatan manual, dan pelaporan."},
{id:"TKP-983", q:"Seorang warga bertanya tentang prosedur pengurusan sertifikat tanah, padahal itu bukan bidang tugas Anda. Sikap Anda:", opts:[{t:"Mengarahkannya ke unit yang tepat dan mengantarnya bila perlu.", s:5},{t:"Mengarahkannya ke bagian yang menangani.", s:4},{t:"Menyuruhnya bertanya sendiri ke bagian lain.", s:3},{t:"Menjawab asal-asalan.", s:2},{t:"Mengusirnya dari loket Anda.", s:1}], ex:"Skor 5: one-stop empathy — warga tidak dipingpong, diarahkan sampai jelas."},
{id:"TKP-984", q:"Rekan senior meremehkan ide Anda tentang digitalisasi antrean perizinan dalam rapat. Sikap Anda:", opts:[{t:"Tetap menyampaikan ide dengan data pendukung secara hormat dan terbuka terhadap masukan.", s:5},{t:"Menyampaikan ide dengan tenang.", s:4},{t:"Diam dan tidak mengusulkan lagi.", s:3},{t:"Emosi dan membantah di forum.", s:2},{t:"Balik meremehkan senior tersebut.", s:1}], ex:"Skor 5: menyampaikan gagasan dengan data dan hormat — inovasi tidak mati oleh senioritas."},
{id:"TKP-985", q:"Fasilitas komputer di ruang pelayanan rusak dan mengganggu pekerjaan. Sudah dilaporkan tetapi belum diperbaiki. Sikap Anda:", opts:[{t:"Melaporkan kembali dengan bukti dampaknya dan mengusulkan solusi sementara.", s:5},{t:"Melaporkan kembali.", s:4},{t:"Membiarkannya dan bekerja seadanya.", s:3},{t:"Merusaknya lebih parah agar cepat diganti.", s:2},{t:"Membawa pulang peralatannya.", s:1}], ex:"Skor 5: menindaklanjuti dengan bukti dan solusi — bukan sekadar mengeluh."},
{id:"TKP-986", q:"Menjelang tutup layanan, atasan meminta Anda lembur dadakan menyelesaikan verifikasi berkas investor yang mendesak. Sikap Anda:", opts:[{t:"Membantu menyelesaikannya dan mengatur prioritas pekerjaan.", s:5},{t:"Bersedia membantu lembur.", s:4},{t:"Menolak dengan halus.", s:3},{t:"Menolak dengan kasar.", s:2},{t:"Pergi tanpa pamit.", s:1}], ex:"Skor 5: loyal dan responsif pada kebutuhan mendesak."},
{id:"TKP-987", q:"Kesalahan rekan kerja menyebabkan berkas yang Anda tangani ikut bermasalah dan Anda ditegur pimpinan. Sikap Anda:", opts:[{t:"Mendiskusikannya dengan rekan untuk mencari solusi bersama dan mencegah terulang.", s:5},{t:"Membicarakannya baik-baik dengannya.", s:4},{t:"Diam meski kesal.", s:3},{t:"Balas dendam dengan menjatuhkannya.", s:2},{t:"Memfitnahnya di depan pimpinan.", s:1}], ex:"Skor 5: menyelesaikan masalah, bukan mencari kambing hitam."},
{id:"TKP-988", q:"Beredar kabar bohong di media sosial bahwa tarif pengurusan izin naik sepuluh kali lipat. Banyak warga resah dan membanjiri kantor. Sikap Anda:", opts:[{t:"Membuat klarifikasi resmi, menyebarkan fakta tarif sebenarnya, dan mengedukasi warga.", s:5},{t:"Mengklarifikasi kabar tersebut.", s:4},{t:"Mengabaikannya.", s:3},{t:"Ikut menyebarkan kabar itu.", s:2},{t:"Membuat kabar bohong tandingan.", s:1}], ex:"Skor 5: melawan hoaks dengan klarifikasi resmi yang cepat dan edukatif."},
{id:"TKP-989", q:"Atasan Anda sakit dan Anda ditunjuk sebagai pelaksana harian. Beberapa keputusan penting harus diambil minggu ini. Sikap Anda:", opts:[{t:"Menjalankan amanah dengan baik, berkonsultasi bila ragu, dan bertindak transparan.", s:5},{t:"Menjalankan tugas sebagaimana mestinya.", s:4},{t:"Bersikap santai menunggu atasan pulih.", s:3},{t:"Memanfaatkan wewenang untuk kepentingan pribadi.", s:2},{t:"Mengambil keputusan sepihak yang menguntungkan diri.", s:1}], ex:"Skor 5: amanah dijalankan penuh — konsultatif, transparan, dan bertanggung jawab."},
{id:"TKP-990", q:"Menjelang akhir tahun, Anda diminta mengisi evaluasi kinerja diri sendiri untuk bahan penilaian. Sikap Anda:", opts:[{t:"Mengisi dengan jujur, merefleksikan kekurangan, dan menyusun rencana perbaikan.", s:5},{t:"Mengisi evaluasi dengan jujur.", s:4},{t:"Mengisi asal-asalan.", s:3},{t:"Melebih-lebihkan pencapaian.", s:2},{t:"Tidak peduli dan tidak mengisi.", s:1}], ex:"Skor 5: refleksi jujur adalah fondasi pengembangan diri."},
{id:"TKP-991", q:"Verifikasi lapangan sebuah kawasan industri membutuhkan tim gabungan dari beberapa OPD. Koordinasinya sering tersendat. Sikap Anda:", opts:[{t:"Berkoordinasi aktif, mengusulkan pembagian tugas yang jelas, dan memantau progres bersama.", s:5},{t:"Ikut berkoordinasi dengan OPD lain.", s:4},{t:"Bersikap pasif menunggu arahan.", s:3},{t:"Menolak terlibat tim gabungan.", s:2},{t:"Menyabotase jadwal tim.", s:1}], ex:"Skor 5: kolaboratif proaktif — inisiatif menggerakkan kerja lintas OPD."},
{id:"TKP-992", q:"Anda berbeda pendapat dengan rekan dari dinas lingkungan hidup soal kelayakan zonasi sebuah kawasan usaha. Diskusi memanas. Sikap Anda:", opts:[{t:"Berdiskusi berbasis data, mencari titik temu, dan mengutamakan kepentingan publik.", s:5},{t:"Berdiskusi dengan kepala dingin.", s:4},{t:"Bersikeras pada pendapat sendiri.", s:3},{t:"Melapor ke pimpinan untuk menekan pihak lain.", s:2},{t:"Memfitnah rekan tersebut.", s:1}], ex:"Skor 5: kolaborasi berbasis data — perbedaan diselesaikan lewat dialog, bukan tekanan."},
{id:"TKP-993", q:"Rekan satu tim menunda-nunda verifikasi berkas sehingga target layanan tim terancam tidak tercapai. Sikap Anda:", opts:[{t:"Mengingatkannya, menawarkan bantuan, dan mengeskalasi bila kebiasaan itu berlanjut.", s:5},{t:"Mengingatkannya baik-baik.", s:4},{t:"Diam karena bukan urusan Anda.", s:3},{t:"Ikut menunda pekerjaan.", s:2},{t:"Mengambil alih lalu memamerkannya ke pimpinan.", s:1}], ex:"Skor 5: peduli tim — mengingatkan, membantu, dan eskalasi prosedural bila perlu."},
{id:"TKP-994", q:"Anda akan cuti seminggu dan ada berkas perizinan penting yang sedang berjalan. Sikap Anda:", opts:[{t:"Membuat dokumentasi serah terima yang lengkap dan membriefing rekan pengganti.", s:5},{t:"Menyerahkan tugas kepada rekan.", s:4},{t:"Menyerahkan seadanya.", s:3},{t:"Tidak melakukan serah terima.", s:2},{t:"Menyembunyikan informasi penting.", s:1}], ex:"Skor 5: serah terima tuntas — pelayanan tidak boleh terganggu oleh cuti."},
{id:"TKP-995", q:"Antar dinas terjadi ego sektoral soal data potensi investasi sehingga investor kebingungan. Sikap Anda:", opts:[{t:"Menginisiasi forum bersama dan berbagi data demi kemudahan investor.", s:5},{t:"Berkoordinasi dengan dinas terkait.", s:4},{t:"Diam mengikuti arus.", s:3},{t:"Menutup data dinas Anda.", s:2},{t:"Membocorkan data untuk menjatuhkan dinas lain.", s:1}], ex:"Skor 5: memecah ego sektoral dengan inisiatif kolaborasi nyata."},
{id:"TKP-996", q:"Tim Anda gagal mencapai target penerbitan izin tepat waktu bulan ini. Suasana tim murung dan saling menyalahkan. Sikap Anda:", opts:[{t:"Mengajak evaluasi bersama, mencari akar masalah, dan menyusun perbaikan.", s:5},{t:"Mengevaluasi kinerja tim.", s:4},{t:"Menyalahkan anggota yang paling lambat.", s:3},{t:"Menyalahkan pimpinan.", s:2},{t:"Memanipulasi laporan capaian.", s:1}], ex:"Skor 5: kegagalan dihadapi bersama — evaluasi objektif tanpa saling menyalahkan."},
{id:"TKP-997", q:"Seorang CPNS baru di unit Anda kebingungan menghadapi pemohon yang marah-marah soal izinnya. Sikap Anda:", opts:[{t:"Mendampingi dan membimbingnya menghadapi situasi itu dengan sabar.", s:5},{t:"Membantunya menangani pemohon.", s:4},{t:"Menyuruhnya belajar sendiri.", s:3},{t:"Menertawakannya.", s:2},{t:"Memanfaatkannya untuk mengerjakan tugas Anda.", s:1}], ex:"Skor 5: mentoring nyata — membimbing junior menghadapi situasi sulit."},
{id:"TKP-998", q:"Rapat koordinasi perizinan berjalan alot karena masing-masing pihak mempertahankan pendiriannya. Sikap Anda:", opts:[{t:"Memfasilitasi diskusi, merangkum poin kesepakatan, dan menindaklanjutinya.", s:5},{t:"Aktif memberi masukan.", s:4},{t:"Diam mengikuti jalannya rapat.", s:3},{t:"Keluar dari ruangan.", s:2},{t:"Memprovokasi perdebatan.", s:1}], ex:"Skor 5: fasilitator konstruktif — mengubah kebuntuan menjadi kesepakatan."},
{id:"TKP-999", q:"Dalam tugas kelompok, satu anggota sangat dominan dan mengabaikan pendapat anggota lain. Sikap Anda:", opts:[{t:"Mengusulkan pembagian peran yang adil dan memastikan semua suara didengar.", s:5},{t:"Mengatur pembagian tugas agar seimbang.", s:4},{t:"Ikut saja apa katanya.", s:3},{t:"Berkonflik dengannya.", s:2},{t:"Menyabotase pekerjaannya.", s:1}], ex:"Skor 5: memastikan keadilan peran — kolaborasi sehat menghargai semua anggota."},
{id:"TKP-1000", q:"Gaya kerja Anda berbeda jauh dengan rekan yang lebih senior: Anda serba digital, ia serba manual. Sering terjadi gesekan. Sikap Anda:", opts:[{t:"Saling belajar dan menyesuaikan — Anda membantunya digital, ia berbagi pengalamannya.", s:5},{t:"Bersikap toleran terhadap perbedaannya.", s:4},{t:"Bersikeras cara Anda yang benar.", s:3},{t:"Meremehkan caranya yang kuno.", s:2},{t:"Bermusuhan dengannya.", s:1}], ex:"Skor 5: perbedaan menjadi saling melengkapi — kolaborasi lintas generasi."},
{id:"TKP-1001", q:"Koordinasi dengan kantor pertanahan soal program PTSL sering tersendat karena jadwal yang tidak sinkron. Sikap Anda:", opts:[{t:"Proaktif menyusun jadwal bersama dan rutin berkomunikasi memantau progres.", s:5},{t:"Berkoordinasi sesuai kebutuhan.", s:4},{t:"Bersikap pasif menunggu kabar.", s:3},{t:"Saling melempar tanggung jawab.", s:2},{t:"Bekerja sama melakukan pungutan.", s:1}], ex:"Skor 5: koordinasi proaktif — jadwal bersama dan komunikasi rutin mencegah tersendat."},
{id:"TKP-1002", q:"Anda dipercaya mengelola dana bersama untuk kegiatan tim. Sikap Anda:", opts:[{t:"Mengelola secara transparan dengan pencatatan dan laporan terbuka.", s:5},{t:"Mengelola dengan jujur.", s:4},{t:"Mengelola seadanya tanpa catatan rinci.", s:3},{t:"Melakukan mark-up pengeluaran.", s:2},{t:"Menggelapkan sebagian dana.", s:1}], ex:"Skor 5: akuntabilitas penuh — transparansi pencatatan membangun kepercayaan tim."},
{id:"TKP-1003", q:"Rekan satu tim jatuh sakit tepat saat tenggat verifikasi berkas penting. Beban kerjanya menumpuk. Sikap Anda:", opts:[{t:"Membantu mengambil alih tugasnya sambil mendoakan kesembuhannya.", s:5},{t:"Membantu menyelesaikan tugasnya.", s:4},{t:"Diam karena itu bukan tugas Anda.", s:3},{t:"Memanfaatkan situasinya untuk pamer ke pimpinan.", s:2},{t:"Membiarkan tugasnya gagal.", s:1}], ex:"Skor 5: solidaritas tim — membantu tanpa pamrih saat rekan kesulitan."},
{id:"TKP-1004", q:"Dua rekan kerja berselisih paham soal pembagian tugas dan tidak saling bicara. Kinerja tim terganggu. Sikap Anda:", opts:[{t:"Memediasi keduanya secara netral hingga mencapai kesepakatan.", s:5},{t:"Mendamaikan keduanya.", s:4},{t:"Diam karena takut ikut terseret.", s:3},{t:"Memihak salah satunya.", s:2},{t:"Mengadu domba keduanya.", s:1}], ex:"Skor 5: mediasi netral — konflik diselesaikan, bukan dibiarkan atau dimanfaatkan."},
{id:"TKP-1005", q:"Tim memutuskan kebijakan pelayanan yang Anda tidak setujui. Keputusan sudah final. Sikap Anda:", opts:[{t:"Mendukung pelaksanaan sambil menyampaikan masukan melalui jalur yang tepat.", s:5},{t:"Mendukung keputusan tim.", s:4},{t:"Diam tetapi bekerja ogah-ogahan.", s:3},{t:"Menyabotase pelaksanaannya.", s:2},{t:"Membocorkan ke pihak luar.", s:1}], ex:"Skor 5: loyal pada keputusan kolektif — keberatan disalurkan lewat jalur resmi."},
{id:"TKP-1006", q:"Anda sudah menguasai sistem perizinan baru, sedangkan rekan-rekan masih kesulitan. Sikap Anda:", opts:[{t:"Mengajari rekan-rekan dan membuat panduan sederhana untuk tim.", s:5},{t:"Mengajari yang bertanya.", s:4},{t:"Pelit berbagi ilmu.", s:3},{t:"Sengaja memberi petunjuk yang salah.", s:2},{t:"Memonopoli pengetahuan untuk terlihat hebat.", s:1}], ex:"Skor 5: berbagi pengetahuan — kompetensi tim naik bersama."},
{id:"TKP-1007", q:"Jadwal piket pelayanan akhir pekan sering tidak dipatuhi sebagian anggota tim. Sikap Anda:", opts:[{t:"Disiplin menjalankan piket dan saling menutupi bila ada yang berhalangan.", s:5},{t:"Menjalankan piket sesuai jadwal.", s:4},{t:"Ikut-ikutan tidak disiplin.", s:3},{t:"Bolos piket.", s:2},{t:"Menitip absen kehadiran.", s:1}], ex:"Skor 5: disiplin plus solidaritas — menutupi kekurangan rekan, bukan ikut bolos."},
{id:"TKP-1008", q:"Target pribadi Anda bertentangan dengan target tim: mengejar target pribadi akan menghambat kerja tim. Sikap Anda:", opts:[{t:"Mendahulukan target tim dan menyinergikan keduanya.", s:5},{t:"Menyeimbangkan keduanya.", s:4},{t:"Mendahulukan target pribadi.", s:3},{t:"Mengorbankan target tim.", s:2},{t:"Mencuri kredit hasil kerja tim.", s:1}], ex:"Skor 5: kepentingan tim di atas ambisi pribadi."},
{id:"TKP-1009", q:"Komunikasi dengan pemerintah desa soal pendataan UMKM sering terhambat birokrasi berlapis. Sikap Anda:", opts:[{t:"Membangun kemitraan rutin dan menyederhanakan alur komunikasi.", s:5},{t:"Berkomunikasi sesuai kebutuhan.", s:4},{t:"Formalitas sekadarnya.", s:3},{t:"Mengabaikan pemerintah desa.", s:2},{t:"Mengintimidasi perangkat desa.", s:1}], ex:"Skor 5: membangun kemitraan — komunikasi dua arah yang rutin dan sederhana."},
{id:"TKP-1010", q:"Kantor mengadakan kerja bakti membersihkan lingkungan. Sebagian pegawai enggan ikut. Sikap Anda:", opts:[{t:"Ikut aktif dan mengajak rekan lain berpartisipasi.", s:5},{t:"Ikut kerja bakti.", s:4},{t:"Mencari-cari alasan.", s:3},{t:"Menolak ikut.", s:2},{t:"Merusak fasilitas saat kerja bakti.", s:1}], ex:"Skor 5: memberi teladan dan mengajak — gotong royong dimulai dari diri sendiri."},
{id:"TKP-1011", q:"Tim Anda ditugasi menyurvei harga pasar untuk penetapan tarif retribusi yang adil. Ada pedagang yang menawarkan 'uang rokok' agar tarif ditetapkan rendah. Sikap Anda:", opts:[{t:"Menolak, melakukan survei objektif, dan menyajikan data akurat.", s:5},{t:"Menolak dan tetap objektif.", s:4},{t:"Menerima tetapi tetap objektif.", s:3},{t:"Berkongkalikong menetapkan tarif.", s:2},{t:"Memanipulasi data survei.", s:1}], ex:"Skor 5: objektivitas data tidak bisa dibeli — survei jujur demi tarif yang adil."},
{id:"TKP-1012", q:"Dinas Anda akan menandatangani kerja sama dengan perusahaan swasta untuk pengembangan kawasan ekonomi. Anda dilibatkan dalam tim. Sikap Anda:", opts:[{t:"Mengawal kepentingan publik, memastikan transparansi, dan mendokumentasikan setiap tahap.", s:5},{t:"Bekerja profesional dalam tim.", s:4},{t:"Asal tanda tangan mengikuti.", s:3},{t:"Membocorkan isi kesepakatan.", s:2},{t:"Menerima fee dari perusahaan.", s:1}], ex:"Skor 5: mengawal kepentingan publik — transparansi dan dokumentasi dalam kerja sama."},
{id:"TKP-1013", q:"Anggota tim Anda dirotasi dan digantikan orang baru yang belum memahami pekerjaan. Sikap Anda:", opts:[{t:"Mendukung rotasi dan mentransfer pengetahuan agar ia cepat beradaptasi.", s:5},{t:"Menerima dan membantunya.", s:4},{t:"Memprotes rotasi tersebut.", s:3},{t:"Memboikot anggota baru.", s:2},{t:"Menyabotase pekerjaannya.", s:1}], ex:"Skor 5: mendukung regenerasi tim — transfer pengetahuan mempercepat adaptasi."},
{id:"TKP-1014", q:"Anda ingin memberi kritik membangun kepada rekan yang sering terlambat menyelesaikan verifikasi berkas. Sikap Anda:", opts:[{t:"Menyampaikannya secara privat dengan bahasa yang baik disertai solusi.", s:5},{t:"Menyampaikannya dengan baik.", s:4},{t:"Diam saja.", s:3},{t:"Menyindirnya di depan umum.", s:2},{t:"Memfitnahnya ke pimpinan.", s:1}], ex:"Skor 5: kritik membangun disampaikan privat, santun, dan solutif."},
{id:"TKP-1015", q:"Tim Anda berhasil meraih predikat pelayanan terbaik tingkat provinsi. Sikap Anda:", opts:[{t:"Merayakan bersama dan mengakui kontribusi setiap anggota.", s:5},{t:"Mengakui keberhasilan tim.", s:4},{t:"Bersikap biasa saja.", s:3},{t:"Mengklaim keberhasilan itu hasil kerja Anda.", s:2},{t:"Mencuri kredit dari rekan.", s:1}], ex:"Skor 5: keberhasilan adalah milik tim — dirayakan dan diakui bersama."},
{id:"TKP-1016", q:"Tim Anda gagal dalam audit kepatuhan pelayanan. Pimpinan meminta pertanggungjawaban. Sikap Anda:", opts:[{t:"Menerima tanggung jawab bersama, mengevaluasi, dan menyusun perbaikan.", s:5},{t:"Mengakui bagian kesalahan Anda.", s:4},{t:"Menyalahkan anggota lain.", s:3},{t:"Cuci tangan.", s:2},{t:"Menjadikan satu orang kambing hitam.", s:1}], ex:"Skor 5: tanggung jawab kolektif — evaluasi jujur tanpa mencari kambing hitam."},
{id:"TKP-1017", q:"Dua kegiatan penting yang Anda tangani jadwalnya bentrok di hari yang sama. Sikap Anda:", opts:[{t:"Bernegosiasi dengan pihak terkait dan mengatur prioritas secara transparan.", s:5},{t:"Mengatur ulang jadwal.", s:4},{t:"Pasrah mengikuti yang mana saja.", s:3},{t:"Egois memilih yang menguntungkan diri.", s:2},{t:"Menyabotase salah satunya.", s:1}], ex:"Skor 5: negosiasi dan prioritas transparan — bentrok diselesaikan profesional."},
{id:"TKP-1018", q:"Dalam tim ada kebiasaan memakai bahasa daerah yang tidak dipahami sebagian anggota, termasuk Anda. Sikap Anda:", opts:[{t:"Mengusulkan penggunaan bahasa yang inklusif sambil tetap menghargai bahasa daerah.", s:5},{t:"Bersikap toleran.", s:4},{t:"Bersikap kaku dan protes.", s:3},{t:"Mengejek bahasa daerah mereka.", s:2},{t:"Mendiskriminasi penggunanya.", s:1}], ex:"Skor 5: inklusif dan menghargai — komunikasi tim tidak boleh menyingkirkan."},
{id:"TKP-1019", q:"Rekan kerja yang lebih tua kesulitan mengoperasikan aplikasi pelaporan digital yang baru. Sikap Anda:", opts:[{t:"Mengajarinya dengan sabar sampai ia bisa mandiri.", s:5},{t:"Membantunya mengoperasikan.", s:4},{t:"Menyuruhnya belajar sendiri.", s:3},{t:"Mengejeknya gaptek.", s:2},{t:"Memanfaatkannya untuk mengambil alih tugasnya.", s:1}], ex:"Skor 5: kesabaran membimbing — tidak ada yang tertinggal dalam transformasi digital."},
{id:"TKP-1020", q:"Anda diminta memberi masukan dalam evaluasi kinerja tim tahunan. Sikap Anda:", opts:[{t:"Memberi masukan jujur, adil, dan membangun untuk kemajuan tim.", s:5},{t:"Memberi masukan jujur.", s:4},{t:"Mengisi asal-asalan.", s:3},{t:"Subjektif berdasarkan suka tidak suka.", s:2},{t:"Memanipulasi untuk menjatuhkan rekan.", s:1}], ex:"Skor 5: evaluasi jujur dan membangun — demi kemajuan tim, bukan sentimen."},
{id:"TKP-1021", q:"Rencana investasi perkebunan berada di atas tanah ulayat masyarakat adat yang belum bersertifikat. Masyarakat adat menolak. Sikap Anda:", opts:[{t:"Menghormati hak adat, memfasilitasi musyawarah dengan melibatkan pemangku adat, dan mencari solusi yang adil.", s:5},{t:"Memediasi antara investor dan masyarakat adat.", s:4},{t:"Mengabaikan keberatan adat demi investasi.", s:3},{t:"Memaksa proyek berjalan.", s:2},{t:"Menyuap tetua adat agar setuju.", s:1}], ex:"Skor 5: hak adat dihormati — musyawarah inklusif mencari solusi adil bagi semua."},
{id:"TKP-1022", q:"Seorang warga pendatang dari luar daerah dilayani dengan ketus oleh petugas karena logatnya berbeda. Ia mengadu kepada Anda. Sikap Anda:", opts:[{t:"Meminta maaf, melayaninya dengan ramah dan setara, serta mengingatkan petugas tersebut.", s:5},{t:"Melayaninya dengan baik.", s:4},{t:"Melayaninya seadanya.", s:3},{t:"Mendiskriminasi karena ia pendatang.", s:2},{t:"Mengusirnya dari kantor.", s:1}], ex:"Skor 5: kesetaraan layanan tanpa memandang asal — plus pembinaan ke petugas."},
{id:"TKP-1023", q:"Seorang warga lansia hanya bisa berbahasa daerah dan tidak paham penjelasan Anda soal prosedur izin dalam bahasa Indonesia. Sikap Anda:", opts:[{t:"Menyesuaikan dengan bahasa yang ia pahami atau meminta bantuan penerjemah hingga ia benar-benar mengerti.", s:5},{t:"Membantunya dengan bahasa sederhana.", s:4},{t:"Tetap menjelaskan dengan bahasa Indonesia.", s:3},{t:"Mengejek logatnya.", s:2},{t:"Menolak melayani.", s:1}], ex:"Skor 5: komunikasi disesuaikan sampai warga paham — pelayanan tanpa sekat bahasa."},
{id:"TKP-1024", q:"Jadwal pelayanan keliling berbenturan dengan upacara adat besar di desa tujuan. Warga meminta jadwal dimundurkan. Sikap Anda:", opts:[{t:"Menyesuaikan jadwal dengan menghormati upacara adat dan mengumumkannya jauh hari.", s:5},{t:"Bertoleransi dan menggeser jadwal.", s:4},{t:"Tetap menjalankan sesuai jadwal awal.", s:3},{t:"Melarang warga mengikuti upacara.", s:2},{t:"Mendenda desa yang tidak hadir.", s:1}], ex:"Skor 5: menghormati adat lewat penyesuaian jadwal yang terencana."},
{id:"TKP-1025", q:"Semangat gotong royong di lingkungan kantor menurun; banyak pegawai individualis. Sikap Anda:", opts:[{t:"Memberi teladan aktif dan mengajak rekan berpartisipasi dalam kegiatan bersama.", s:5},{t:"Ikut serta dalam gotong royong.", s:4},{t:"Bersikap pasif.", s:3},{t:"Menolak ikut.", s:2},{t:"Merusak fasilitas bersama.", s:1}], ex:"Skor 5: teladan dan ajakan — budaya gotong royong dibangun dari contoh."},
{id:"TKP-1026", q:"Ada ketegangan di tim karena perbedaan agama antar anggota menjelang hari raya. Sikap Anda:", opts:[{t:"Menghormati keyakinan masing-masing, mengakomodasi kebutuhan ibadah, dan menjaga keharmonisan.", s:5},{t:"Bersikap toleran.", s:4},{t:"Bersikap kaku.", s:3},{t:"Menyindir keyakinan rekan.", s:2},{t:"Mendiskriminasi rekan beda agama.", s:1}], ex:"Skor 5: toleransi aktif — akomodasi nyata, bukan sekadar slogan."},
{id:"TKP-1027", q:"Program perhutanan sosial akan dijalankan di kawasan yang dikelola masyarakat dengan kearifan lokal turun-temurun. Sikap Anda:", opts:[{t:"Melibatkan masyarakat, memadukan kearifan lokal dengan program resmi.", s:5},{t:"Menghargai kearifan lokal mereka.", s:4},{t:"Mengabaikan praktik tradisional.", s:3},{t:"Melarang praktik tradisional.", s:2},{t:"Mengeksploitasi hutan untuk keuntungan.", s:1}], ex:"Skor 5: kearifan lokal adalah modal — dipadukan, bukan digusur program."},
{id:"TKP-1028", q:"Sengketa batas kebun antar warga desa biasa diselesaikan lewat musyawarah adat. Salah satu pihak meminta difasilitasi resmi. Sikap Anda:", opts:[{t:"Memfasilitasi musyawarah dengan menghormati mekanisme adat yang sah dan mencatat hasilnya.", s:5},{t:"Mendukung penyelesaian lewat adat.", s:4},{t:"Mengabaikan mekanisme adat.", s:3},{t:"Mengintervensi keputusan adat.", s:2},{t:"Menerima suap untuk memihak.", s:1}], ex:"Skor 5: menghormati dan memfasilitasi — kearifan lokal diakui dalam koridor hukum."},
{id:"TKP-1029", q:"Seorang pegawai ingin mengenakan pakaian adat pada acara resmi kantor. Atasan ragu mengizinkan. Sikap Anda:", opts:[{t:"Mendukung dan mengusulkan agar pakaian adat diakomodasi pada momen yang tepat.", s:5},{t:"Mengizinkannya.", s:4},{t:"Bersikap kaku pada aturan seragam.", s:3},{t:"Melarangnya.", s:2},{t:"Menghukumnya.", s:1}], ex:"Skor 5: kebanggaan budaya diakomodasi — identitas tidak bertentangan dengan profesionalisme."},
{id:"TKP-1030", q:"Tamu dari daerah lain memiliki pantangan makanan tertentu dalam acara jamuan dinas. Sikap Anda:", opts:[{t:"Memperhatikan pantangannya dan menyiapkan alternatif yang sesuai.", s:5},{t:"Menanyakan kebutuhannya.", s:4},{t:"Mengabaikan dan menyajikan seadanya.", s:3},{t:"Memaksanya mencicipi.", s:2},{t:"Mengejek pantangannya.", s:1}], ex:"Skor 5: perhatian pada detail keberagaman — tamu dihormati keyakinannya."},
{id:"TKP-1031", q:"Anak muda desa mendukung pembangunan kawasan wisata, sedangkan para tetua menolak karena khawatir merusak adat. Sikap Anda:", opts:[{t:"Menjembatani dialog antar generasi untuk mencari kesepakatan yang menghormati keduanya.", s:5},{t:"Mendengarkan aspirasi semua pihak.", s:4},{t:"Memihak salah satu kelompok.", s:3},{t:"Mengabaikan penolakan tetua.", s:2},{t:"Mengadu domba keduanya.", s:1}], ex:"Skor 5: jembatan antar generasi — dialog mencari titik temu, bukan pemenang."},
{id:"TKP-1032", q:"Aturan baru melarang praktik tradisional tertentu yang bertentangan dengan kelestarian lingkungan. Masyarakat menolak. Sikap Anda:", opts:[{t:"Menyosialisasikan secara persuasif dengan masa transisi dan alternatif yang disepakati.", s:5},{t:"Menjelaskan alasan aturan dengan baik.", s:4},{t:"Memaksa penerapan seketika.", s:3},{t:"Langsung mendenda pelanggar.", s:2},{t:"Menggunakan kekerasan.", s:1}], ex:"Skor 5: perubahan persuasif — transisi bertahap dengan alternatif yang disepakati."},
{id:"TKP-1033", q:"Warga kelompok minoritas di daerah terpencil sulit mengakses layanan perizinan karena jarak dan informasi. Sikap Anda:", opts:[{t:"Melakukan jemput bola dan memastikan mereka terlayani setara.", s:5},{t:"Membantu saat mereka datang.", s:4},{t:"Melayani seperti biasa.", s:3},{t:"Mengabaikan kesulitan mereka.", s:2},{t:"Mendiskriminasi mereka.", s:1}], ex:"Skor 5: keadilan akses — negara aktif menjangkau yang terpinggirkan."},
{id:"TKP-1034", q:"Banyak warga di wilayah kerja Anda tidak fasih berbahasa Indonesia sehingga sering salah paham soal prosedur layanan. Sikap Anda:", opts:[{t:"Mengusulkan penyediaan penerjemah atau melatih staf berbahasa daerah setempat.", s:5},{t:"Menyediakan bantuan penerjemah.", s:4},{t:"Meminta warga membawa penerjemah sendiri.", s:3},{t:"Menolak melayani yang tidak paham.", s:2},{t:"Mengejek mereka.", s:1}], ex:"Skor 5: solusi sistemik atas kendala bahasa — bukan menyalahkan warga."},
{id:"TKP-1035", q:"Ritual panen adat berbenturan dengan jadwal tanam program pemerintah yang harus tepat waktu. Sikap Anda:", opts:[{t:"Menyelaraskan jadwal program dengan menghormati ritual adat.", s:5},{t:"Menghormati ritual tersebut.", s:4},{t:"Mengabaikan ritual adat.", s:3},{t:"Melarang ritual.", s:2},{t:"Mendenda yang mengikuti ritual.", s:1}], ex:"Skor 5: program dan adat diselaraskan — keduanya bisa berjalan berdampingan."},
{id:"TKP-1036", q:"Terjadi ketegangan antar kelompok pedagang beda suku di pasar daerah. Suasana memanas. Sikap Anda:", opts:[{t:"Memediasi dengan melibatkan tokoh kedua kelompok hingga tercapai kesepakatan damai.", s:5},{t:"Mendamaikan keduanya.", s:4},{t:"Menyerahkan sepenuhnya ke aparat.", s:3},{t:"Memihak kelompok mayoritas.", s:2},{t:"Memprovokasi salah satu pihak.", s:1}], ex:"Skor 5: mediasi inklusif — tokoh kedua pihak dilibatkan untuk perdamaian."},
{id:"TKP-1037", q:"Proyek pembangunan jalan daerah akan melewati situs budaya yang dianggap keramat warga. Sikap Anda:", opts:[{t:"Mengusulkan penyesuaian trase atau pelestarian situs sambil mencari solusi teknis.", s:5},{t:"Melaporkan ke dinas terkait.", s:4},{t:"Mengabaikan keberatan warga.", s:3},{t:"Menggusur situs tersebut.", s:2},{t:"Menerima suap untuk menggusur.", s:1}], ex:"Skor 5: pembangunan menghormati warisan — solusi teknis dicari, bukan digusur."},
{id:"TKP-1038", q:"Perempuan adat tidak dilibatkan dalam musyawarah desa soal pemanfaatan lahan. Sikap Anda:", opts:[{t:"Mendorong pelibatan setara perempuan dalam setiap musyawarah.", s:5},{t:"Mendukung keterlibatan mereka.", s:4},{t:"Mengabaikan ketidaksetaraan itu.", s:3},{t:"Melarang mereka ikut.", s:2},{t:"Merendahkan mereka.", s:1}], ex:"Skor 5: kesetaraan aktif — suara perempuan adalah bagian keputusan desa."},
{id:"TKP-1039", q:"Anak-anak jalanan berkeliaran di kawasan wisata dan mengganggu pengunjung. Sikap Anda:", opts:[{t:"Membina mereka dan berkoordinasi dengan dinas sosial untuk penanganan.", s:5},{t:"Membantu mencarikan solusi.", s:4},{t:"Mengusirnya.", s:3},{t:"Menggunakan kekerasan.", s:2},{t:"Mengeksploitasi mereka.", s:1}], ex:"Skor 5: pembinaan humanis — anak jalanan dibina lewat koordinasi, bukan kekerasan."},
{id:"TKP-1040", q:"Jadwal piket pelayanan bertepatan dengan hari raya keagamaan sebagian pegawai. Sikap Anda:", opts:[{t:"Mengatur piket secara adil dengan menghormati hari raya masing-masing.", s:5},{t:"Bersikap toleran dalam penjadwalan.", s:4},{t:"Bersikap kaku pada jadwal.", s:3},{t:"Memprotes penjadwalan.", s:2},{t:"Mendiskriminasi pegawai tertentu.", s:1}], ex:"Skor 5: keadilan jadwal yang menghormati keberagaman keyakinan."},
{id:"TKP-1041", q:"Anda ditugaskan mendampingi tamu dari daerah dengan adat istiadat yang sangat berbeda. Sikap Anda:", opts:[{t:"Mempelajari adatnya dan bersikap hormat sesuai kebiasaannya.", s:5},{t:"Bersikap sopan dan ramah.", s:4},{t:"Bersikap cuek.", s:3},{t:"Melanggar adatnya tanpa sadar dan tidak peduli.", s:2},{t:"Menghina adatnya.", s:1}], ex:"Skor 5: menghormati keberagaman dengan mempelajari dan menyesuaikan diri."},
{id:"TKP-1042", q:"Seorang warga memaki dengan bahasa kasar karena izinnya ditolak. Pegawai lain terpancing emosi. Sikap Anda:", opts:[{t:"Tetap tenang, profesional, dan menjelaskan dengan sabar.", s:5},{t:"Bersabar menghadapinya.", s:4},{t:"Membalas dengan nada tinggi.", s:3},{t:"Membentaknya balik.", s:2},{t:"Melakukan kekerasan.", s:1}], ex:"Skor 5: profesionalisme teruji saat diprovokasi — tenang dan tetap melayani."},
{id:"TKP-1043", q:"Musyawarah perencanaan pembangunan desa tidak melibatkan penyandang disabilitas. Sikap Anda:", opts:[{t:"Mendorong akomodasi penuh agar mereka bisa berpartisipasi setara.", s:5},{t:"Melibatkan mereka.", s:4},{t:"Mengabaikan ketidakhadiran mereka.", s:3},{t:"Menolak usulan pelibatan.", s:2},{t:"Merendahkan mereka.", s:1}], ex:"Skor 5: partisipasi inklusif — difabel adalah warga yang suaranya setara."},
{id:"TKP-1044", q:"Di loket pembayaran retribusi pasar, banyak pedagang lansia kesulitan antre lama sambil berdiri. Sikap Anda:", opts:[{t:"Membuat jalur khusus lansia dengan tempat duduk dan pelayanan ramah.", s:5},{t:"Mendahulukan para lansia.", s:4},{t:"Melayani seperti biasa.", s:3},{t:"Mengabaikan kesulitan mereka.", s:2},{t:"Mengusir yang protes.", s:1}], ex:"Skor 5: solusi konkret untuk lansia — jalur khusus plus kenyamanan."},
{id:"TKP-1045", q:"Bencana longsor melanda dan banyak warga mengungsi. Posko membutuhkan relawan dari pegawai. Sikap Anda:", opts:[{t:"Sigap menjadi relawan dan berkoordinasi dengan tim penanggulangan.", s:5},{t:"Membantu di posko.", s:4},{t:"Menunggu ditunjuk.", s:3},{t:"Menolak dengan alasan tugas.", s:2},{t:"Memanfaatkan bantuan untuk pribadi.", s:1}], ex:"Skor 5: sigap dan terkoordinasi — kemanusiaan didahulukan."},
{id:"TKP-1046", q:"Banyak anak putus sekolah menjadi pedagang kaki lima tanpa izin di kawasan Anda. Sikap Anda:", opts:[{t:"Membina mereka dan menghubungkan dengan program pelatihan serta perizinan yang mudah.", s:5},{t:"Membantu mencarikan solusi.", s:4},{t:"Membiarkannya.", s:3},{t:"Menggusur mereka.", s:2},{t:"Memungut liar dari mereka.", s:1}], ex:"Skor 5: pembinaan memberdayakan — anak putus sekolah dibantu naik kelas lewat program."},
{id:"TKP-1047", q:"Kelompok kesenian lokal berlatih dengan suara keras hingga mengganggu pelayanan di kantor yang berdekatan. Sikap Anda:", opts:[{t:"Berdialog mengatur waktu latihan sekaligus mendukung pelestarian kesenian.", s:5},{t:"Memediasi kedua pihak.", s:4},{t:"Melarang latihan.", s:3},{t:"Mendenda kelompok kesenian.", s:2},{t:"Membubarkan paksa.", s:1}], ex:"Skor 5: ketertiban dan budaya berjalan bersama — dialog menghasilkan pengaturan."},
{id:"TKP-1048", q:"Penyuluhan kesehatan ditolak warga karena bertentangan dengan kepercayaan tradisional setempat. Sikap Anda:", opts:[{t:"Mengedukasi secara persuasif dengan melibatkan tokoh masyarakat yang dipercaya.", s:5},{t:"Mengedukasi dengan sabar.", s:4},{t:"Mengabaikan penolakan.", s:3},{t:"Memaksa warga ikut.", s:2},{t:"Menghina kepercayaan mereka.", s:1}], ex:"Skor 5: edukasi persuasif lewat tokoh dipercaya — perubahan tanpa melukai."},
{id:"TKP-1049", q:"Pasangan yang menikah secara adat kesulitan mencatatkan perkawinannya karena tidak paham administrasi. Sikap Anda:", opts:[{t:"Membantu proses pencatatan dengan menghormati prosesi adatnya.", s:5},{t:"Memfasilitasi pencatatannya.", s:4},{t:"Menolak karena rumit.", s:3},{t:"Mempersulit prosesnya.", s:2},{t:"Memungut biaya tidak resmi.", s:1}], ex:"Skor 5: administrasi negara menghormati adat — dibantu sampai tuntas."},
{id:"TKP-1050", q:"Gelombang PHK di sebuah perusahaan menimbulkan banyak pengangguran di daerah Anda. Sikap Anda:", opts:[{t:"Menghubungkan mereka dengan program pelatihan kerja dan informasi lowongan.", s:5},{t:"Membantu memberi informasi.", s:4},{t:"Simpati saja.", s:3},{t:"Mengabaikan.", s:2},{t:"Memanfaatkan keputusasaan mereka.", s:1}], ex:"Skor 5: menghubungkan dengan solusi nyata — pelatihan dan lowongan."},
{id:"TKP-1051", q:"Sistem OSS error tepat saat Anda membantu verifikasi berkas investor. Investor tampak kecewa. Sikap Anda:", opts:[{t:"Menjelaskan dengan jujur, memproses manual sementara, melaporkan gangguan, dan memantau hingga pulih.", s:5},{t:"Membantu dengan cara manual.", s:4},{t:"Menyuruhnya mencoba lagi nanti.", s:3},{t:"Menyalahkan sistem pusat.", s:2},{t:"Menawarkan jalur manual berbayar.", s:1}], ex:"Skor 5: transparan, solutif, dan bertanggung jawab memantau hingga tuntas."},
{id:"TKP-1052", q:"Anda mengetahui data pribadi pemohon izin bocor dan disalahgunakan pihak tak bertanggung jawab. Sikap Anda:", opts:[{t:"Melaporkan insiden, mengamankan akses, dan mengevaluasi sistem keamanannya.", s:5},{t:"Melaporkan kejadian.", s:4},{t:"Diam karena takut disalahkan.", s:3},{t:"Menutupi kejadian.", s:2},{t:"Menjual data tersebut.", s:1}], ex:"Skor 5: melindungi data warga — lapor, amankan, evaluasi."},
{id:"TKP-1053", q:"Anda menerima email mencurigakan yang mengatasnamakan pimpinan meminta transfer data retribusi. Sikap Anda:", opts:[{t:"Tidak mengklik, memverifikasi ke pimpinan lewat jalur resmi, dan melaporkan sebagai dugaan phishing.", s:5},{t:"Menghapus dan melaporkannya.", s:4},{t:"Mengabaikannya.", s:3},{t:"Mengklik tautannya.", s:2},{t:"Menyebarkannya ke grup.", s:1}], ex:"Skor 5: verifikasi dan lapor — kehati-hatian digital melindungi data dinas."},
{id:"TKP-1054", q:"Arsip perizinan di unit Anda masih menumpuk dalam bentuk kertas dan sulit dicari. Sikap Anda:", opts:[{t:"Menginisiasi digitalisasi arsip secara sistematis dan bertahap.", s:5},{t:"Merapikan arsip yang ada.", s:4},{t:"Membiarkannya.", s:3},{t:"Membuang arsip lama.", s:2},{t:"Menjual arsip ke pihak luar.", s:1}], ex:"Skor 5: inisiatif digitalisasi — arsip tertib mendukung layanan cepat."},
{id:"TKP-1055", q:"Dinas mulai menerapkan tanda tangan elektronik, tetapi banyak pegawai enggan beralih dari tanda tangan basah. Sikap Anda:", opts:[{t:"Mempelajari, menerapkan, dan membantu rekan beradaptasi.", s:5},{t:"Menggunakannya.", s:4},{t:"Menolak beralih.", s:3},{t:"Memalsukan tanda tangan elektronik.", s:2},{t:"Menyabotase sistemnya.", s:1}], ex:"Skor 5: adaptif dan menularkan — perubahan didukung dengan membantu sesama."},
{id:"TKP-1056", q:"Kabar bohong soal kenaikan tarif retribusi sepuluh kali lipat viral di media sosial dan menimbulkan kepanikan pedagang. Sikap Anda:", opts:[{t:"Membuat klarifikasi resmi dengan cepat disertai data tarif sebenarnya.", s:5},{t:"Mengklarifikasi kabar tersebut.", s:4},{t:"Mengabaikannya.", s:3},{t:"Ikut menyebarkan.", s:2},{t:"Membuat kabar bohong tandingan.", s:1}], ex:"Skor 5: melawan hoaks dengan klarifikasi resmi yang cepat dan berbasis data."},
{id:"TKP-1057", q:"Rekan kerja meminta kata sandi akun sistem perizinan Anda dengan alasan darurat. Sikap Anda:", opts:[{t:"Menolak dan mengedukasi tentang keamanan akun serta prosedur akses resmi.", s:5},{t:"Menolak memberikannya.", s:4},{t:"Memberikannya.", s:3},{t:"Memakai akun milik orang lain.", s:2},{t:"Membobol akun atasan.", s:1}], ex:"Skor 5: keamanan akun tidak bisa ditawar — tolak plus edukasi."},
{id:"TKP-1058", q:"Anda menyadari data perizinan penting belum pernah dicadangkan (backup). Sikap Anda:", opts:[{t:"Mengusulkan dan melaksanakan pencadangan rutin.", s:5},{t:"Melakukan pencadangan.", s:4},{t:"Mengabaikannya.", s:3},{t:"Menghapus data lama.", s:2},{t:"Menyabotase data.", s:1}], ex:"Skor 5: pencegahan proaktif — backup rutin melindungi data negara."},
{id:"TKP-1059", q:"Aplikasi pencatatan pajak daerah error dan data setoran hari ini belum tersimpan. Sikap Anda:", opts:[{t:"Mencatat manual sementara, mengamankan bukti setoran, dan melaporkan ke tim IT.", s:5},{t:"Melaporkan gangguan.", s:4},{t:"Menunggu sistem pulih.", s:3},{t:"Menginput asal-asalan.", s:2},{t:"Memanipulasi data setoran.", s:1}], ex:"Skor 5: data diamankan dulu — pencatatan manual plus pelaporan."},
{id:"TKP-1060", q:"Banyak wajib pajak lansia gagap teknologi saat diminta membayar pajak daring. Sikap Anda:", opts:[{t:"Mendampingi dengan sabar dan membuat panduan sederhana yang mudah diikuti.", s:5},{t:"Membantu mereka membayar.", s:4},{t:"Menyuruh anaknya yang mengurus.", s:3},{t:"Menolak melayani.", s:2},{t:"Mengejek mereka.", s:1}], ex:"Skor 5: kesabaran plus panduan — transformasi digital tidak meninggalkan lansia."},
{id:"TKP-1061", q:"Komputer di unit pelayanan diduga terkena ransomware; file-file penting tidak bisa dibuka dan muncul pesan tebusan. Sikap Anda:", opts:[{t:"Mengisolasi perangkat, melaporkan insiden, dan memulihkan dari cadangan data.", s:5},{t:"Melaporkan kejadian.", s:4},{t:"Membayar tebusan yang diminta.", s:3},{t:"Panik dan menghapus semua file.", s:2},{t:"Menyembunyikan kejadian.", s:1}], ex:"Skor 5: respons insiden yang benar — isolasi, lapor, pulihkan dari backup; tebusan tidak dibayar."},
{id:"TKP-1062", q:"Akun media sosial resmi dinas dibanjiri kritik pedas soal pelayanan perizinan yang lambat. Sikap Anda:", opts:[{t:"Menanggapi secara profesional, menindaklanjuti keluhan, dan memperbaiki layanan.", s:5},{t:"Menanggapi dengan baik.", s:4},{t:"Mengabaikan komentar.", s:3},{t:"Menghapus semua komentar negatif.", s:2},{t:"Menyerang balik pengkritik.", s:1}], ex:"Skor 5: media sosial dikelola profesional — kritik ditindaklanjuti, bukan dibungkam."},
{id:"TKP-1063", q:"Anda diminta mempresentasikan potensi investasi daerah dalam pertemuan video dengan calon investor asing. Sikap Anda:", opts:[{t:"Menyiapkan data akurat, berpenampilan profesional, dan mempresentasikan dengan percaya diri.", s:5},{t:"Mengikuti pertemuan dengan baik.", s:4},{t:"Asal mengikuti.", s:3},{t:"Menolak ikut.", s:2},{t:"Membocorkan data sensitif.", s:1}], ex:"Skor 5: profesionalisme penuh — persiapan matang demi citra daerah."},
{id:"TKP-1064", q:"Dinas mewajibkan seluruh pegawai mengikuti pelatihan daring (e-learning) ASN. Sikap Anda:", opts:[{t:"Mengikuti dengan serius dan menerapkan ilmunya dalam pekerjaan.", s:5},{t:"Mengikuti pelatihan.", s:4},{t:"Asal mengklik sampai selesai.", s:3},{t:"Menitip kehadiran ke rekan.", s:2},{t:"Memakai joki.", s:1}], ex:"Skor 5: pengembangan kompetensi dijalani sungguh-sungguh dan diterapkan."},
{id:"TKP-1065", q:"Anda menemukan data ganda wajib retribusi yang menyebabkan sebagian pedagang ditagih dua kali. Sikap Anda:", opts:[{t:"Memverifikasi, membersihkan data ganda, mengoreksi tagihan, dan mencegah terulang.", s:5},{t:"Memperbaiki data yang ganda.", s:4},{t:"Membiarkannya.", s:3},{t:"Memanfaatkan untuk pungutan ganda.", s:2},{t:"Memungut dua kali dengan sengaja.", s:1}], ex:"Skor 5: koreksi tuntas plus pencegahan — keadilan bagi wajib retribusi."},
{id:"TKP-1066", q:"Dinas menerapkan pembayaran retribusi nontunai (QRIS), tetapi banyak pedagang menolak dan memilih tunai. Sikap Anda:", opts:[{t:"Menyosialisasikan manfaatnya, mendampingi penggunaan, dengan masa transisi yang wajar.", s:5},{t:"Menerapkan sesuai ketentuan.", s:4},{t:"Membiarkan pembayaran tunai terus.", s:3},{t:"Tetap memungut tunai untuk diselewengkan.", s:2},{t:"Menggelapkan setoran tunai.", s:1}], ex:"Skor 5: transisi persuasif — sosialisasi dan pendampingan, bukan pemaksaan."},
{id:"TKP-1067", q:"Situs web resmi dinas diretas dan menampilkan konten tidak pantas. Sikap Anda:", opts:[{t:"Melaporkan, memulihkan situs, dan mengevaluasi keamanannya.", s:5},{t:"Melaporkan kejadian.", s:4},{t:"Diam berharap tidak ketahuan.", s:3},{t:"Menutupi kejadian.", s:2},{t:"Memanfaatkan akses peretas.", s:1}], ex:"Skor 5: respons cepat — lapor, pulihkan, evaluasi keamanan."},
{id:"TKP-1068", q:"Rekan mengusulkan memakai aplikasi kecerdasan buatan gratis untuk mengolah data pribadi pemohon izin. Sikap Anda:", opts:[{t:"Menolak bila berisiko bocor, mempelajari aturannya, dan memakai hanya yang aman dan resmi.", s:5},{t:"Mempelajari dulu keamanannya.", s:4},{t:"Ikut memakai tanpa pikir panjang.", s:3},{t:"Mengunggah semua data ke aplikasi.", s:2},{t:"Membocorkan data ke publik.", s:1}], ex:"Skor 5: inovasi tetap mengutamakan perlindungan data pribadi warga."},
{id:"TKP-1069", q:"Isi grup pesan dinas yang membahas strategi penagihan retribusi bocor ke publik. Sikap Anda:", opts:[{t:"Mengevaluasi tata kelola grup, menetapkan aturan, dan melaporkan kebocoran.", s:5},{t:"Mengatur ulang keanggotaan grup.", s:4},{t:"Diam saja.", s:3},{t:"Menyebarkan isi grup.", s:2},{t:"Menjual informasi dinas.", s:1}], ex:"Skor 5: evaluasi dan penataan — kebocoran ditindaklanjuti sistemik."},
{id:"TKP-1070", q:"Anda diminta memperbarui dasbor capaian PAD yang dipantau pimpinan setiap minggu. Sikap Anda:", opts:[{t:"Memperbarui dengan data akurat dan transparan tepat waktu.", s:5},{t:"Mengisi sesuai data.", s:4},{t:"Mengisi asal-asalan.", s:3},{t:"Memanipulasi angkanya.", s:2},{t:"Memalsukan laporan.", s:1}], ex:"Skor 5: data akurat dan tepat waktu — dasar pengambilan keputusan pimpinan."},
{id:"TKP-1071", q:"Di grup pesan pegawai beredar konten bermuatan ekstremisme yang menghasut kebencian. Beberapa rekan ikut menyebarkannya. Sikap Anda:", opts:[{t:"Tidak ikut menyebar, melaporkan kontennya, dan mengedukasi rekan tentang bahayanya.", s:5},{t:"Melaporkan konten tersebut.", s:4},{t:"Diam dan keluar dari grup.", s:3},{t:"Meneruskannya.", s:2},{t:"Ikut menyebarkan.", s:1}], ex:"Skor 5: menolak, melapor, mengedukasi — ASN benteng persatuan."},
{id:"TKP-1072", q:"Seorang penceramah di lingkungan kantor menyampaikan ceramah provokatif yang menyudutkan kelompok tertentu. Sikap Anda:", opts:[{t:"Melaporkan kepada pimpinan dan mengupayakan pembinaan agar tidak terulang.", s:5},{t:"Melaporkan kejadian.", s:4},{t:"Diam saja.", s:3},{t:"Ikut menghadiri dan mendukung.", s:2},{t:"Mengundangnya kembali.", s:1}], ex:"Skor 5: intoleransi dicegah lewat pelaporan dan pembinaan resmi."},
{id:"TKP-1073", q:"Rekan kerja mengajak Anda bergabung dalam kelompok yang memperjuangkan paham khilafah dan menolak Pancasila. Sikap Anda:", opts:[{t:"Menolak tegas, melaporkan ajakan itu, dan mengajaknya kembali ke NKRI.", s:5},{t:"Menolak dan melaporkannya.", s:4},{t:"Diam dan menjauh.", s:3},{t:"Mendengarkan ajakannya.", s:2},{t:"Bergabung dengannya.", s:1}], ex:"Skor 5: setia pada Pancasila — tolak, lapor, dan bina kembali."},
{id:"TKP-1074", q:"Rekan kerja kerap mengunggah ujaran kebencian bernuansa SARA di media sosialnya. Sikap Anda:", opts:[{t:"Mengingatkannya tentang etika ASN bermedia sosial dan melaporkannya bila berlanjut.", s:5},{t:"Mengingatkannya.", s:4},{t:"Diam saja.", s:3},{t:"Menyukai unggahannya.", s:2},{t:"Ikut menyebarkan.", s:1}], ex:"Skor 5: mengingatkan plus eskalasi — ASN wajib menjaga ruang digital."},
{id:"TKP-1075", q:"Di ruang kerja rekan Anda terpasang simbol organisasi terlarang. Sikap Anda:", opts:[{t:"Melaporkan dan memastikan simbol itu ditertibkan sesuai aturan.", s:5},{t:"Melaporkan temuan.", s:4},{t:"Diam.", s:3},{t:"Membiarkannya.", s:2},{t:"Ikut memasang.", s:1}], ex:"Skor 5: tidak ada toleransi simbol terlarang — lapor dan tertibkan."},
{id:"TKP-1076", q:"Seorang rekan menunjukkan sikap intoleran kepada pegawai berbeda agama, misalnya menolak satu tim dengannya. Sikap Anda:", opts:[{t:"Menegurnya, membela yang didiskriminasi, dan melaporkannya untuk pembinaan.", s:5},{t:"Menegur rekan tersebut.", s:4},{t:"Diam.", s:3},{t:"Ikut menjauhinya.", s:2},{t:"Memprovokasi permusuhan.", s:1}], ex:"Skor 5: keberagaman dibela aktif — tegur, bela, laporkan untuk dibina."},
{id:"TKP-1077", q:"Seseorang menggalang donasi di kantor untuk kelompok yang diduga menyalurkan dana ke jaringan ekstrem. Sikap Anda:", opts:[{t:"Menolak berdonasi dan melaporkan penggalangan tersebut.", s:5},{t:"Menolak berdonasi.", s:4},{t:"Diam saja.", s:3},{t:"Ikut berdonasi.", s:2},{t:"Ikut menggalang dana.", s:1}], ex:"Skor 5: waspada pendanaan ekstremisme — tolak dan laporkan."},
{id:"TKP-1078", q:"Dalam diskusi santai, seorang rekan menyatakan Pancasila sudah tidak relevan dan harus diganti. Sikap Anda:", opts:[{t:"Menegaskan kesetiaan pada Pancasila, meluruskan, dan melaporkannya.", s:5},{t:"Menolak pendapatnya.", s:4},{t:"Diam.", s:3},{t:"Simpatik pada pendapatnya.", s:2},{t:"Ikut menyetujui.", s:1}], ex:"Skor 5: Pancasila harga mati — diluruskan dan dilaporkan."},
{id:"TKP-1079", q:"Dalam proses rekrutmen pegawai, Anda mencium indikasi ada calon yang terafiliasi paham radikal. Sikap Anda:", opts:[{t:"Melakukan verifikasi ketat dan melaporkan indikasi sesuai prosedur.", s:5},{t:"Memverifikasi latar belakangnya.", s:4},{t:"Mengabaikan indikasi.", s:3},{t:"Meloloskannya.", s:2},{t:"Membantu meloloskannya.", s:1}], ex:"Skor 5: seleksi berintegritas — verifikasi ketat melindungi institusi."},
{id:"TKP-1080", q:"Khotbah di masjid kantor berisi provokasi yang menghasut jemaah membenci pemerintah. Sikap Anda:", opts:[{t:"Berkoordinasi dengan takmir untuk pembinaan dan melaporkan konten provokatif.", s:5},{t:"Melaporkan kejadian.", s:4},{t:"Diam saja.", s:3},{t:"Mendukung isi khotbah.", s:2},{t:"Menyebarluaskan rekamannya.", s:1}], ex:"Skor 5: rumah ibadah dijaga dari provokasi — koordinasi dan pembinaan."}
];
